#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""扩展语法数据生成脚本 - 生成463条语法点"""
import json, os
topics = []
def T(id,cat,lvl,title,summary,detail,*ex):
    topics.append({"id":id,"category":cat,"level":lvl,"title":title,
        "summary":summary,"detail":detail,
        "examples":[{"en":e,"cn":c} for e,c in ex]})
def B(id,t,s,d,*ex): T(id,"basics",1,t,s,d,*ex)
def N(id,t,s,d,*ex): T(id,"tense",2,t,s,d,*ex)
def C(id,t,s,d,*ex): T(id,"clause",3,t,s,d,*ex)
def A(id,t,s,d,*ex): T(id,"advanced",4,t,s,d,*ex)
def M(id,t,s,d,*ex): T(id,"mastery",5,t,s,d,*ex)

