# === BASICS 硬编码 80条 ===
B("noun_countable_uncountable","可数与不可数名词","可数有单复数可用a/an，不可数不可直接计数","可数名词有单复数形式，可用a/an修饰，如a book/two books。\n不可数名词无复数，不可用a/an，如water/information/advice。\n计量用量词：a piece of advice, a glass of water。\n常见不可数：furniture, luggage, equipment, homework, knowledge, news。",("I have two books.","我有两本书。"),("She gave me advice.","她给了我建议。"))
B("noun_plural_formation","名词复数构成","一般加s，s/x/ch/sh结尾加es，辅音+y变i加es","规则：一般加s(book→books)；s/x/ch/sh加es(bus→buses, watch→watches)；辅音+y变i加es(city→cities)；f/fe变v加es(leaf→leaves)；o结尾有生命加es(potato→potatoes)，无生命加s(photo→photos)。",("There are many cities in China.","中国有很多城市。"),("She bought two knives.","她买了两把刀。"))
B("noun_irregular_plural","不规则名词复数","man→men, child→children, foot→feet等特殊变化","不规则复数需单独记忆：变元音(man→men, foot→feet, tooth→teeth, mouse→mice)；加en(child→children, ox→oxen)；单复同形(sheep, deer, fish, series)；外来词(analysis→analyses, datum→data, phenomenon→phenomena)。",("Two men and three women are waiting.","两男三女在等。"),("The children are playing with mice.","孩子们在玩老鼠。"))
B("noun_collective","集体名词","family/team/class表集合体，谓语可单可复","集体名词如family/team/class/group/audience/committee/police。\n整体看谓语单数：My family is large.\n强调个体谓语复数：My family are watching TV.\npolice和cattle永远用复数：The police are coming.",("My family is going on a trip.","我家要去旅行。"),("The committee are divided.","委员们意见分歧。"))
B("noun_proper","专有名词","人名地名等首字母大写，通常不加冠词","专有名词首字母大写。通常不加冠词：China, Beijing, John, Monday。\n由普通名词组成加the：the United States, the Great Wall。\n复数专有名词加the：the Alps, the Philippines。\n江河海洋加the：the Yangtze, the Pacific。",("She lives in New York.","她住在纽约。"),("The Great Wall is famous.","长城很有名。"))
B("noun_material","物质名词","water/bread/iron等表物质，通常不可数","物质名词表材料物质，不可数：water, milk, bread, meat, rice, paper, wood, iron, gold, glass。\n计量用量词：a glass of water, a loaf of bread, a piece of meat, a bar of chocolate。\n表种类可用复数：fruits(各种水果), steels(各种钢)。",("I'd like a glass of milk.","我要一杯牛奶。"),("This ring is made of gold.","这戒指是金的。"))
B("noun_abstract","抽象名词","happiness/freedom等表概念品质，通常不可数","抽象名词表品质/状态/概念，一般不可数：happiness, freedom, love, courage, knowledge, information, advice, news, progress。\n有些可加a/an表实例：a success(成功的事), a knowledge of English。\n常用后缀：-ness/-tion/-ment/-ity/-ship。",("Happiness is more important than wealth.","幸福比财富重要。"),("We made great progress.","我们进步很大。"))
B("noun_possessive_s","名词所有格's","有生命事物加's表示所属关系","单数加's：Tom's book, my mother's car。\n以s结尾复数加'：the students' room。\n不以s结尾复数加's：children's day。\n并列各有各自加：Tom's and Mary's books；共有最后加：Tom and Mary's room。\n表时间/距离：today's news, a week's holiday。",("This is Tom's bicycle.","这是汤姆的自行车。"),("It is Women's Day.","今天是妇女节。"))
B("noun_possessive_of","of所有格","用of表示无生命事物的所属关系","of所有格用于无生命名词：the door of the room, the title of the book。\n有生命名词较长时也可用of：the plays of Shakespeare。\nof还可表同位/数量：the City of Beijing, a cup of tea。\n有生命优先's，无生命用of。",("The cover of the book is red.","书的封面是红色的。"),("What is the title of the movie?","电影叫什么名字？"))
B("noun_double_possessive","双重所有格","a friend of mine结构兼用of和物主代词","双重所有格：限定词+名词+of+名词性物主代词/所有格。\na friend of mine, two books of hers, a friend of my father's。\nof前须有限定词(a/an/this/some/数词)。\n表部分所属，暗含'中的一个'。",("He is a friend of mine.","他是我的一个朋友。"),("This is a book of my father's.","这是我父亲的一本书。"))
B("noun_compound","复合名词","两词组合成新名词如bookstore, mother-in-law","书写形式：合写(bookstore, classroom)；分写(bus stop, ice cream)；连字符(mother-in-law)。\n复数在中心词后加s：bookstores, bus stops。\n含连字符在主要名词后加s：mothers-in-law, editors-in-chief。",("I bought books at the bookstore.","我在书店买了书。"),("The check-in counter is there.","值机柜台在那边。"))
B("noun_countable_expressions","不可数名词计量表达","用a piece of, a cup of等量词计量不可数名词","量词搭配：a piece of(advice/news/music), a glass of water, a bottle of milk, a loaf of bread, a bar of chocolate, a slice of pizza, a sheet of paper, a grain of rice, a drop of water。\n量词可变复数：two cups of coffee。",("I need a piece of paper.","我需要一张纸。"),("She ate a slice of pizza.","她吃了一片披萨。"))
B("noun_singular_plural_same","单复数同形名词","sheep/deer/fish/series等单复数不变","单复数同形：sheep, deer, fish, salmon, series, species, aircraft, means, headquarters。\n根据限定词和谓语判断单复数：this sheep is / these sheep are。\nfish表同种用单数，表多种用fishes。",("One sheep is missing.","一只羊丢了。"),("Several aircraft were seen.","看到几架飞机。"))
B("noun_plural_meaning_change","单复数意义不同的名词","glass/glasses, paper/papers等单复数意义不同","glass(玻璃)/glasses(眼镜)；paper(纸)/papers(文件)；time(时间)/times(时代)；work(工作)/works(作品/工厂)；iron(铁)/irons(熨斗)；people(人们)/peoples(民族)；custom(风俗)/customs(海关)。",("She wears glasses to read papers.","她戴眼镜看文件。"),("Times have changed.","时代变了。"))
B("noun_common_suffixes","名词常见后缀","-er/-or/-tion/-ment/-ness/-ity等后缀构名词","表人：-er(teacher), -or(actor), -ist(scientist), -ian(musician)。\n表动作：-tion(education), -ment(development)。\n表品质：-ness(happiness), -ity(ability)。\n表抽象：-hood(childhood), -ship(friendship), -dom(freedom)。",("The teacher explained education.","老师解释了教育。"),("His happiness comes from friendship.","他的幸福来自友谊。"))
B("adj_comparative_regular","形容词比较级","单音节加er，多音节加more，后接than","构成：单音节加-er(tall→taller)；以e加-r(nice→nicer)；重读闭音节双写(big→bigger)；辅音+y变i加er(happy→happier)；多音节加more(beautiful→more beautiful)。\n句型：A is+比较级+than B。",("Tom is taller than Jack.","汤姆比杰克高。"),("This is more interesting.","这个更有趣。"))
B("adj_superlative_regular","形容词最高级","单音节加est，多音节加most，前加the","构成：单音节加-est(tallest)；以e加-st(largest)；双写加est(biggest)；变i加est(happiest)；多音节加most(most beautiful)。\n用法：前加the；比较范围in/of；one of the+最高级+复数。",("She is the tallest in the class.","她是班上最高的。"),("This is one of the best books.","这是最好的书之一。"))
B("adj_irregular_comparison","不规则形容词比较等级","good→better→best, bad→worse→worst等","good/well→better→best；bad/ill→worse→worst；many/much→more→most；little→less→least；far→farther/further→farthest/furthest；old→older/elder→oldest/eldest。\nelder表家庭长幼不与than连用。",("This is the best movie.","这是最好的电影。"),("My health is worse than before.","身体比以前差了。"))
B("adj_order","形容词排列顺序","限定+主观+大小+年龄+颜色+产地+材质+用途+名词","口诀：限观大龄色产地材途名。\n顺序：限定词→观点(beautiful)→大小(big)→年龄(old)→颜色(red)→产地(Chinese)→材质(wooden)→用途(sports)→名词。\n例：a beautiful large old red Chinese wooden dining table。",("She wore a beautiful small white silk dress.","她穿了一件漂亮的小号白色丝绸裙。"),("I bought a large old brown wooden table.","我买了一张大的旧棕色木桌。"))
B("adj_ed_ing","-ed与-ing形容词","-ed表感受修饰人，-ing表特征修饰物","-ing形容词表事物特征'令人…的'：interesting, exciting, boring, surprising。\n-ed形容词表人感受'感到…的'：interested, excited, bored, surprised。\n人作主语用-ed，物作主语用-ing。",("The movie was boring; I was bored.","电影无聊，我无聊。"),("The news is exciting; we are excited.","消息令人兴奋，我们兴奋。"))
B("adj_predicate_only","表语形容词","afraid/alive/alone/asleep只作表语不作定语","以a-开头的形容词只作表语：afraid, alive, alone, asleep, awake, aware, ashamed, alike。\n作定语需换词：the afraid boy→the frightened boy；the asleep baby→the sleeping baby；an ill person→a sick person。\nalone(独自)vs lonely(孤独)。",("I am afraid of dogs.","我怕狗。"),("The baby is asleep.","婴儿睡着了。"))
B("adj_common_suffixes","形容词后缀","-ful/-less/-ous/-ive/-al/-y等后缀构形容词","-ful(beautiful, careful, useful)；-less(careless, useless, hopeless)；-ous(dangerous, famous, nervous)；-ive(active, creative, effective)；-al(natural, cultural, educational)；-y(sunny, healthy, noisy)。",("She is a creative artist.","她是有创造力的艺术家。"),("The weather is sunny today.","今天天气晴朗。"))
B("adj_enough_position","enough的位置","enough修饰形/副在后，修饰名词前后均可","enough作副词修饰形/副放其后：good enough, old enough, fast enough。\nenough作形容词修饰名词可前后：enough money / money enough。\nenough...to do：old enough to drive。\ntoo...to：too tired to walk。",("He is old enough to drive.","他够年龄开车了。"),("We don't have enough money.","我们没有足够的钱。"))
B("adj_as_as","as...as同级比较","as+原级+as表同等，否定用not as/so...as","肯定：as+原级+as。否定：not as/so+原级+as。\n倍数放第一个as前：twice as big as, three times as long as。\nas...as possible=尽可能：as soon as possible。\n第二个as后可省略比较对象。",("He is as tall as his brother.","他和哥哥一样高。"),("This room is twice as big.","这个房间是两倍大。"))
B("adj_comparative_modifiers","比较级修饰词","much/a lot/far/even加强，a little/a bit减弱","加强比较级：much better, a lot taller, far more important, even worse, still higher。\n减弱比较级：a little better, a bit cheaper, slightly higher。\n精确比较：two years older, three meters longer。\n注意：very不修饰比较级，用much。",("This is much better.","这个好得多。"),("She is a little taller.","她高一点。"))
B("adj_own","own的用法","own强调所属，放在物主代词后","own放物主代词后：my own room, his own car。\non one's own=独自/靠自己：I did it on my own。\nof one's own=属于自己的：He has a house of his own。\nown也作动词'拥有'。",("I saw it with my own eyes.","我亲眼所见。"),("She runs her own business.","她经营自己的生意。"))
B("adj_quantifiers","数量形容词some/any","some用于肯定，any用于否定和疑问","some用于肯定句：I have some money。\nany用于否定/疑问：I don't have any. / Do you have any?\nsome可用于疑问句表请求：Would you like some tea?\nany用于肯定表'任何'：Any student can join。\n复合词：someone/anything/nobody。",("There are some apples.","有一些苹果。"),("Would you like some tea?","想喝茶吗？"))
B("adv_time","时间副词","now/today/yesterday等表时间，放句首或句末","时间副词：now, today, yesterday, tomorrow, soon, already, just, still, yet, recently, lately, ago, before。\n位置：通常句末(I saw him yesterday)；强调时句首(Yesterday I went there)；already/just放句中(She has already left)。",("I will finish it tomorrow.","我明天完成。"),("Yesterday we went to the zoo.","昨天我们去了动物园。"))
B("adv_place","地点副词","here/there/outside等表地点，放句末","地点副词：here, there, everywhere, nowhere, somewhere, anywhere, abroad, home, upstairs, downstairs, nearby, ahead。\n位置：通常句末(Come here)；强调时句首(Here comes the bus)。\nhome/abroad前不加to：go home, go abroad。",("Please come here.","请过来。"),("They went abroad last year.","他们去年出国了。"))
B("adv_degree","程度副词","very/quite/too/rather等修饰形容词表程度","程度副词：very(很), quite(相当), too(太), so(如此), rather(颇), pretty(相当), fairly(还算), extremely(极其), completely(完全), slightly(稍微), a little(一点)。\nvery修饰原级不修饰比较级；比较级用much。",("She is very happy.","她很开心。"),("It is rather cold.","相当冷。"))
B("adv_manner","方式副词","quickly/carefully/well等表方式，放动词后","方式副词表动作方式：quickly, carefully, slowly, happily, beautifully, well, fast, hard。\n多数由形容词+ly构成。不规则：good→well, fast→fast, hard→hard。\n位置：动词后或宾语后(She sings beautifully)。\n注意：hard(努力)vs hardly(几乎不)；late(迟)vs lately(最近)。",("She speaks English fluently.","她英语流利。"),("He works hard.","他努力工作。"))
B("adv_frequency","频率副词","always/usually/often等表频率，放be后实义动词前","频率从高到低：always(总是)>usually(通常)>often(经常)>sometimes(有时)>seldom(很少)>never(从不)。\n位置：be动词后(She is always late)；实义动词前(I always get up early)；助动词后(I have never been)。\n提问用How often。",("She is always the first to arrive.","她总是第一个到。"),("I usually have breakfast at seven.","我通常七点吃早饭。"))
B("adv_position_rules","副词位置规则","频率副词be后实义动词前，方式→地点→时间顺序","基本位置：句首(连接副词)、句中(be/助动词后实义动词前)、句末(方式+地点+时间)。\n多个副词排列：方式→地点→时间(She sang beautifully in the hall yesterday)。\n副词不可插在动词和宾语之间。enough放形容词后。",("She always works hard here.","她总是在这里努力工作。"),("They left quietly yesterday.","他们昨天悄悄离开了。"))
B("adv_formation","副词的构成","多数形容词加ly，以y结尾变i加ly，以le结尾去e加y","构成规则：一般+ly(slow→slowly)；辅音+y变i加ly(happy→happily)；以le去e加y(simple→simply)；以ic加ally(basic→basically)。\n注意：有些词兼作形/副：fast, hard, early, late, high。\n有些-ly词是形容词：friendly, lovely, lonely。",("He drives carefully.","他小心驾驶。"),("She easily solved the problem.","她轻松解决难题。"))
B("adv_irregular_forms","不规则副词","good→well, fast→fast, hard→hard等无ly变化","不加-ly的副词(形副同形)：fast, hard, early, late, high, long, far, straight, near。\n形式相同意义不同：hard(努力)vs hardly(几乎不)；late(迟)vs lately(最近)；near(近)vs nearly(几乎)；high(高)vs highly(高度地)。",("She works hard.","她努力工作。"),("He arrived late.","他迟到了。"))
B("adv_comparative_superlative","副词比较级最高级","单音节加er/est，多音节用more/most","单音节副词加-er/-est：fast→faster→fastest, hard→harder→hardest。\n多音节用more/most：quickly→more quickly→most quickly。\n不规则：well→better→best, badly→worse→worst。\n比较级+than；最高级前the可省。",("She runs faster than him.","她比他跑得快。"),("Who sings the best?","谁唱得最好？"))
B("adv_too_enough","too与enough","too表过度，enough表足够，位置不同","too+形/副：too big, too fast。too...to do(太…而不能)：too tired to walk。\n形/副+enough：good enough, old enough。enough+名词：enough money。\nenough...to do(足够…可以)：strong enough to carry。",("This box is too heavy to carry.","箱子太重搬不动。"),("She is old enough to drive.","她够年龄开车。"))
B("prep_in_on_at_time","介词in/on/at表时间","in表较长时段，on表具体某天，at表具体时刻","in+较长时段：in January, in spring, in 2024, in the morning。\non+具体某天：on Monday, on July 4th, on a cold morning。\nat+具体时刻：at 3 o'clock, at noon, at night, at Christmas。\non time(准时), in time(及时)。",("I was born in 2000.","我2000年出生。"),("The train leaves at 8.","火车八点发车。"))
B("prep_in_on_at_place","介词in/on/at表地点","in表大空间内，on表表面，at表具体地点","in+大空间/内部：in Beijing, in the room, in the box。\non+表面/楼层：on the table, on the wall, on the second floor。\nat+具体地点：at the station, at school, at home, at 123 Main St。\nin the wall(墙内)vs on the wall(墙面上)。",("She lives in Beijing.","她住在北京。"),("The book is on the table.","书在桌上。"))
B("prep_by","介词by的用法","by表方式/被动/时间/交通，用法多样","表交通：by bus, by car, by train(不加冠词)。\n表被动执行者：written by Shakespeare。\n表方式：by chance, by hand, by phone。\n表时间'到…为止'：by Friday, by the end of the year。\nby oneself=独自。by+doing=通过做…。",("She goes to work by subway.","她坐地铁上班。"),("You must finish by Friday.","你周五前必须完成。"))
B("prep_with","介词with的用法","with表伴随/工具/拥有/方式","表伴随：go with friends。\n表工具：cut with a knife, write with a pen。\n表拥有：a girl with long hair, a house with a garden。\n表原因：shake with cold, red with anger。\nwith复合结构：with the door open, with him standing there。",("She cut the cake with a knife.","她用刀切蛋糕。"),("The girl with blue eyes is my sister.","蓝眼女孩是我妹妹。"))
B("prep_through","介词through","through表穿过/经历/通过，强调从内部经过","表空间穿过：walk through the forest, look through the window。\n表方式'通过'：succeed through hard work, learn through practice。\n表经历：go through difficulties。\n表时间'整个期间'：through the night, Monday through Friday。\nthrough(内部穿过)vs across(表面横过)。",("We walked through the forest.","我们穿过森林。"),("She succeeded through hard work.","她通过努力成功了。"))
B("prep_of","介词of","of表所属/构成/关于，使用最广的介词之一","表所属：the capital of China, a friend of mine。\n表材料：a ring of gold, a house of stone。\n表原因：die of cancer, proud of you, tired of waiting。\n表数量：a cup of tea, a lot of people, millions of stars。\nof常替代's用于无生命名词所有格。",("The capital of France is Paris.","法国首都是巴黎。"),("I am proud of you.","我为你骄傲。"))
B("prep_about","介词about","about表关于/大约/周围","表话题：talk about sports, a book about history, worry about exams。\n表大约：about 20 people, about three o'clock。\n表周围：look about, wander about。\nbe about to do=即将做：The meeting is about to start。\nHow about...?=…怎么样？",("Let's talk about the plan.","谈谈计划。"),("There are about 50 students.","大约有50个学生。"))
B("prep_for","介词for","for表目的/原因/持续/交换/目的地","表目的：study for the exam, a gift for you。\n表原因：famous for, thank you for。\n表持续：for three hours, for ten years。\n表交换：exchange A for B。\n表目的地：leave for New York。\n表赞成：Are you for or against?\nfor+时段vs since+时间点。",("I bought a gift for you.","我给你买了礼物。"),("She has lived here for ten years.","她住了十年。"))
B("prep_between_among","between与among","between用于两者之间，among用于三者以上","between用于两者：between you and me, the distance between A and B。\n也用于多个独立个体间：a treaty between three countries。\namong用于三者以上'在…之中'：among the crowd, among the trees。\nbetween强调两两关系，among强调群体中。",("The choice is between you and me.","选择在你我之间。"),("She stood among the crowd.","她站在人群中。"))
B("prep_over_above","over与above","over表正上方/覆盖，above表高于不一定正上方","over：正上方(a lamp over the table)；覆盖(put a blanket over him)；越过(jump over the wall)；超过(over 50 people)；期间(over the years)。\nabove：高于(The picture is above the sofa)；超过(above average, above zero)。\nover强调垂直正上方，above只强调高于。",("A bridge goes over the river.","桥横跨河面。"),("The temperature is above zero.","气温在零度以上。"))
B("prep_under_below","under与below","under表正下方/被覆盖，below表低于不一定正下方","under：正下方(the cat under the table)；被覆盖(under the blanket)；少于(under 18)；过程中(under construction)。\nbelow：低于(sank below the horizon, below zero)；以下(sign below)。\nunder强调正下方，below只强调低于某水平。",("The cat is under the table.","猫在桌下。"),("The bridge is under construction.","桥在建中。"))
B("prep_in_into","in与into","in表位置在某空间内，into表进入的动作方向","in表静态位置'在…内'：in the room, in the box。\ninto表动态方向'进入'：go into the room, jump into the water。\ninto还表转变：turn water into ice, translate into Chinese。\nin可作副词：come in。",("She is in the kitchen.","她在厨房。"),("He jumped into the pool.","他跳进游泳池。"))
B("prep_to_toward","to与toward(s)","to表方向/终点，toward表朝向不一定到达","to：方向/目的地(go to school, fly to London)；接受者(give to him)；比较(prefer A to B)。\ntoward(s)：朝向(walk toward the door)；趋势(toward evening)；对于(attitude toward work)。\nto强调到达，toward强调方向。toward(美)/towards(英)。",("She walked to the station.","她走到车站。"),("He walked toward the door.","他朝门走去。"))
B("prep_common_phrases","常见介词短语","in fact, on time, at last等固定介词短语搭配","in短语：in fact, in time, in danger, in a hurry, in charge of, in general, in return, in vain, in addition。\non短语：on time, on duty, on purpose, on sale, on average, on business。\nat短语：at first, at last, at least, at once, at present, at the same time。\nby短语：by chance, by mistake, by hand, by the way, by far。",("In fact, I agree.","事实上我同意。"),("The meeting started on time.","会议准时开始。"))
B("conj_both_and","both...and","连接两个并列成分，表'既…又…'，谓语用复数","both...and连接对等成分：both名词/形容词/动词。\n连接主语谓语用复数：Both Tom and Mary are students。\n连接成分须结构对等。\nboth可单独用：Both of them came。",("She speaks both English and French.","她既说英语又说法语。"),("Both Tom and Jerry are friends.","汤姆和杰瑞都是朋友。"))
B("conj_either_or","either...or","表选择，连接两个成分，谓语就近一致","either...or表'要么…要么…'。连接主语时谓语就近一致。\nEither you or he is wrong. (与he一致用is)\nEither he or you are wrong. (与you一致用are)\n否定形式：neither...nor。",("You can either stay or leave.","你可以留下或离开。"),("Either you or he is responsible.","要么你要么他负责。"))
B("conj_neither_nor","neither...nor","表否定两者，谓语就近一致","neither...nor表'既不…也不…'，否定两者。\n连接主语谓语就近一致：Neither you nor he is wrong.\n连接成分须结构对等。\nneither可单独用：Neither of them is right。",("She neither smokes nor drinks.","她既不抽烟也不喝酒。"),("Neither you nor he is wrong.","你和他都没错。"))
B("conj_not_only_but_also","not only...but also","表'不但…而且'，连接对等成分","not only...but also表'不但…而且…'，强调后者。\n连接主语谓语就近一致。\n倒装(强调时)：Not only does she sing, but she also dances.\nalso可省略：She is not only beautiful but intelligent.\n两成分须结构对等。",("She not only sings but also dances.","她不仅唱歌还跳舞。"),("Not only did he apologize, but he also paid.","他不仅道歉还赔了。"))
B("conj_and_or_but","and/or/but基础连词","and表并列，or表选择，but表转折","and：并列(Tom and Jerry)；顺序(washed and dried)；因果(Study hard, and you'll pass)。\nor：选择(tea or coffee)；否则(Hurry up, or you'll be late)。\nbut：转折(rich but unhappy)；除外(everyone but me)。\nand和but不可连用。",("I like apples and oranges.","我喜欢苹果和橘子。"),("Hurry up, or you'll be late.","快点否则会迟到。"))
B("conj_so_yet","so与yet","so表因果'所以'，yet表转折'然而'","so(所以)：It was late, so I went home.\nso+adj+that(如此…以至于)：so tired that I fell asleep.\nso that(以便)：I got up early so that I could catch the train.\nyet(然而)：He is rich, yet unhappy.\nyet也作副词'还'：not yet。",("It was raining, so I stayed home.","下雨了所以待家。"),("She is rich, yet unhappy.","她富有但不开心。"))
B("conj_for_as","for与as","for表补充原因，as表因为/作为/当…时","for(补充原因，不放句首)：He must be ill, for he looks pale.\nas(当…时/因为/作为)：As I was walking, I saw him. / As it rained, we stayed. / She works as a nurse.\nas...as(同级比较)：as tall as。\nas if(仿佛)：He looks as if he were ill。",("He must be tired, for he worked all night.","他一定累了，因为工作了一整夜。"),("As I was leaving, the phone rang.","我正要走时电话响了。"))
B("conj_subordinating_basic","基础从属连词","when/because/if/although等引导从句","时间：when, while, before, after, since, until, as soon as。\n原因：because, since, as, now that。\n条件：if, unless, as long as, in case。\n让步：although, though, even though。\n目的：so that, in order that。\n结果：so...that, such...that。\nalthough和but不同时用。",("When I arrived, he was sleeping.","我到时他在睡。"),("Because it rained, we stayed home.","因为下雨我们待家。"))
B("pron_reflexive","反身代词","myself/yourself/himself等表动作回到主语自身","反身代词：myself, yourself, himself, herself, itself, ourselves, yourselves, themselves。\n作宾语(动作回主语)：I hurt myself. / She taught herself English.\n强调用法：I myself did it. / I saw it myself.\n固定搭配：enjoy oneself(玩得开心), help oneself to(请自便), by oneself(独自), teach oneself(自学)。",("She taught herself English.","她自学英语。"),("Help yourselves to some fruit.","请随便吃水果。"))
B("pron_reciprocal","相互代词","each other和one another表互相","each other(两者间)：The two sisters love each other.\none another(三者以上)：The members help one another.\n所有格：each other's books, one another's problems。\n介词+相互代词：talk to each other, look at each other。\n不作主语。",("The two sisters love each other.","两姐妹很相爱。"),("They looked at each other in surprise.","他们惊讶地看着对方。"))
B("pron_relative_basic","关系代词基础","who/whom/whose/which/that引导定语从句","who(人,主语)：The man who lives next door is a doctor.\nwhom(人,宾语,可省)：The man (whom) I met is a doctor.\nwhose(所属)：The girl whose hair is long is my friend.\nwhich(物)：The book which is on the table is mine.\nthat(人/物,限制性从句)：The book that I bought.\n非限制性从句不用that。",("The man who is talking is my father.","说话的人是我父亲。"),("The book that I bought is interesting.","我买的书很有趣。"))
B("pron_interrogative","疑问代词","who/whom/whose/what/which用于提问","who(谁,主语)：Who is that man?\nwhom(谁,宾语)：Whom did you meet? (口语常用Who)\nwhose(谁的)：Whose book is this?\nwhat(什么)：What do you want?\nwhich(哪个,有选择范围)：Which do you prefer, tea or coffee?\nwho问身份，what问事物，which问选择。",("Who is the girl over there?","那女孩是谁？"),("Which do you prefer, tea or coffee?","你更喜欢哪个，茶还是咖啡？"))
B("pron_indefinite","不定代词","someone/anything/nobody/everyone等表不确定指代","some系列(肯定)：someone, something, somewhere。\nany系列(否定/疑问/条件)：anyone, anything, anywhere。肯定句表'任何'。\nno系列(否定)：no one/nobody, nothing, nowhere。\nevery系列：everyone/everybody, everything, everywhere。\n不定代词作主语谓语单数。修饰词放其后：something important。",("Someone is knocking at the door.","有人在敲门。"),("Nobody knows the answer.","没人知道答案。"))
B("pron_demonstrative","指示代词","this/that/these/those指示近处或远处","this/these(近处)：This is my book. / These are hers.\nthat/those(远处)：That is her house. / Those were happy days.\n打电话：This is John. / Is that Mary?\n介绍：This is my friend Tom.\n指上文：He was late. That's why he was angry。",("This is my new car.","这是我的新车。"),("Those were happy days.","那是一段快乐的时光。"))
B("pron_possessive","物主代词","my/your/his与mine/yours/his，形容词性与名词性","形容词性(后接名词)：my, your, his, her, its, our, their → my book。\n名词性(单独使用)：mine, yours, his, hers, its, ours, theirs → This is mine.\n名词性=形容词性+名词：This pen is mine = This is my pen.\nof+名词性(双重所有格)：a friend of mine。",("This is my book and that is yours.","这是我的书那是你的。"),("Our school is bigger than theirs.","我们学校比他们的大。"))
B("pron_personal","人称代词","I/you/he/she/it/we/they主格与宾格","主格(作主语)：I, you, he, she, it, we, they。\n宾格(作宾语/表语)：me, you, him, her, it, us, them。\n主格作主语(She is a teacher)；宾格作动词/介词宾语(I like her. Listen to me)。\n并列主语礼貌顺序：你>他>她>我。",("She is my best friend.","她是我最好的朋友。"),("I gave the book to him.","我把书给了他。"))
B("pron_it_basic","it的基本用法","it指物/天气/时间/距离/形式主语/形式宾语","指事物：Where is my book? — It is on the desk.\n指天气/时间/距离：It is raining. / It is 8 o'clock. / It is two miles.\n形式主语：It is important to learn English. / It takes me two hours.\n形式宾语：I find it hard to get up early.\n强调句：It was Tom who broke the window。",("It is a beautiful day.","今天天气真好。"),("It is important to learn English.","学好英语很重要。"))
B("pron_one_ones","one与ones替代","one替代可数单数，ones替代复数，避免重复","one替代上文单数可数名词：I don't like this pen; I want a new one.\nones替代复数：These apples are bad; give me fresh ones.\nthe one特指单数，the ones特指复数。\n前面有形容词：a red one, the big one。\n不可数名词不用one替代。",("I don't like this shirt; show me another one.","我不喜欢这件衬衫，给我看另一件。"),("These cookies are good; I want more ones.","这些饼干好，我还要一些。"))
B("article_a_an","冠词a/an","a用于辅音音素前，an用于元音音素前","a+辅音音素：a book, a car, a university(ju:), a one-eyed man。\nan+元音音素：an apple, an egg, an umbrella, an hour(h不发音), an honest man, an MBA。\n表泛指'一个'：I have a pen.\n表种类：A dog is loyal. = Dogs are loyal.\n表'每一'：three times a day, sixty miles an hour。",("She is a university student.","她是大学生。"),("I'll be there in an hour.","我一小时后到。"))
B("article_the","定冠词the","the表特指，用于双方共知或再次提到的人/物","特指：Pass me the salt. / The man in blue is my teacher.\n再次提到：I bought a book. The book is interesting.\n独一无二：the sun, the moon, the earth。\n序数词/最高级前：the first, the best。\nthe+形容词(表一类人)：the rich, the poor。\nthe+姓氏复数(全家)：the Smiths。\n乐器前：play the piano。",("The sun rises in the east.","太阳从东方升起。"),("She plays the piano well.","她钢琴弹得好。"))
B("article_zero","零冠词","不使用冠词的场合","复数泛指：Dogs are loyal.\n不可数泛指：Water is important.\n专有名词：China, Beijing, John。\n三餐/运动/学科：have breakfast, play football, study math。\n固定搭配：at home, go to school, by bus, in bed。\ngo to school(去上学)vs go to the school(去学校办事)。",("Dogs are loyal animals.","狗是忠诚的动物。"),("She goes to school by bus.","她坐公交上学。"))
B("article_idiomatic","冠词惯用搭配","固定搭配中的冠词用法需整体记忆","加the：in the morning, in the end, on the other hand, out of the question。\n不加：at noon/night, at home/school, by bus/car, on foot, by chance, by heart, day and night, hand in hand。\n对比：in front of(在…前面)vs in the front of(在…前部)；out of question(没问题)vs out of the question(不可能)。",("She goes to school by bus.","她坐公交上学。"),("In the end, we succeeded.","最后我们成功了。"))
B("article_geographical","地理名称冠词","江河海洋加the，湖泊山峰国名一般不加the","加the：江河(the Yangtze), 海洋(the Pacific), 群岛(the Philippines), 山脉(the Alps), 沙漠(the Sahara), 由普通名词组成的国家(the United States)。\n不加the：湖泊(Lake Michigan), 单座山(Mount Tai), 国家(China), 城市(Beijing), 街道(Wall Street), 公园(Central Park)。",("The Yangtze is the longest river in China.","长江是中国最长河流。"),("Mount Everest is the highest mountain.","珠峰是最高的山。"))
B("article_abstract_material","抽象名词与物质名词冠词","泛指不加，特指加the，种类加a/an","泛指不加：Knowledge is power. / Water is essential.\n特指加the：The water in this river is clean.\n加a/an表种类/实例：a success(成功的事), a coffee(一杯咖啡), a heavy rain。\n有描绘性形容词时可用a/an：a fine tea, a heavy snow。\na knowledge of English(英语知识)。",("Knowledge is more important than money.","知识比金钱重要。"),("The coffee in this shop is excellent.","这家店的咖啡很棒。"))
B("numeral_cardinal_ordinal","基数词与序数词","基数词表数量，序数词表顺序","基数词：one, two, three...hundred, thousand, million。21-99用连字符：twenty-one。hundred前有数字不加s：three hundred。\n序数词：first, second, third, fifth, eighth, ninth, twelfth, twentieth。构成：一般加th；第一/二/三特殊；ty结尾变y为i加eth。\n序数词前加the：the first floor。也可加a/an表'又一个'：a third time。",("There are thirty-one days in May.","五月有31天。"),("She lives on the third floor.","她住三楼。"))
B("numeral_fraction","分数表达","分子用基数词，分母用序数词，分子大于1分母加s","1/3 = one third (a third)。1/2 = a half。1/4 = a quarter。\n分子大于1分母加s：2/3 = two thirds, 3/4 = three quarters。\n带分数：2 1/3 = two and one third。\n分数+名词：one third of the students。\n谓语与of后名词一致：Two thirds of the water is polluted. / Two thirds of students are boys。",("One third of the students are boys.","三分之一的学生是男生。"),("She ate two thirds of the cake.","她吃了三分之二的蛋糕。"))
B("numeral_decimal","小数表达","小数点读point，小数点前后分别读数字","0.5 = zero point five / point five。\n3.14 = three point one four。\n0.25 = zero point two five。\n小数+名词：3.5 meters = three point five meters。\n小数点后数字逐个读：3.14159 = three point one four one five nine。\n百分数：50% = fifty percent, 3.5% = three point five percent。",("The box weighs 2.5 kilograms.","箱子重2.5公斤。"),("The temperature is 36.5 degrees.","体温36.5度。"))
B("numeral_multiple","倍数表达","倍数+as...as或倍数+比较级或倍数+the+名词","结构1：倍数+as+原级+as → twice as big as(两倍大)。\n结构2：倍数+比较级+than → three times bigger than(大三倍)。\n结构3：倍数+the+名词+of → twice the size of(两倍大小)。\n动词：double(翻番), triple(三倍)。\n1倍=the same as。",("This room is twice as large as that one.","这个房间是那个两倍大。"),("The price has doubled in five years.","五年内价格翻了一番。"))
B("numeral_percentage","百分比表达","percent或%表示百分率，谓语与of后名词一致","50% = fifty percent。100% = one hundred percent。\n谓语与of后名词一致：50% of students are boys(复数). / 50% of water is clean(不可数)。\n搭配：increase by 20%(增长20%)；increase to 50%(增长到50%)；20% off(打八折)。\n3 out of 5 = 五分之三。",("Sixty percent of the students passed.","百分之六十的学生通过了。"),("Prices increased by 15% this year.","今年价格涨了15%。"))
B("numeral_numbering","编号表达","编号用名词+基数词或the+序数词+名词","名词+基数词：Page 5, Room 101, Bus No. 5, World War II。\nthe+序数词+名词：the fifth page, the third lesson。\n电话号码逐个读：555-8901 → five five five, eight nine oh one。\n年份：1999 = nineteen ninety-nine; 2008 = two thousand and eight。\n时间：7:30 = seven thirty / half past seven。",("Open your books to Page 15.","打开书翻到第15页。"),("Take Bus No. 5 to the station.","坐5路公交去车站。"))
B("numeral_date_time","日期和时间表达","日期、时间、时刻的表达方式","日期：May 4(th) / the fourth of May / May the fourth。\n时间：7:00 = seven (o'clock); 7:30 = seven thirty / half past seven; 7:15 = seven fifteen / a quarter past seven; 7:45 = seven forty-five / a quarter to eight。\n世纪年代：the 21st century, the 1990s (the nineties)。\n时刻表：at 8 a.m., from 9 to 5。",("The meeting starts at 2:30 p.m.","会议下午两点半开始。"),("She was born on May 4th, 2000.","她2000年5月4日出生。"))
# === TENSE 硬编码 28条 ===
N("present_simple_vs_continuous","一般现在时vs现在进行时","一般现在表习惯，进行时表此时此刻正在发生","一般现在时表经常性/习惯性/真理：She works here every day.\n现在进行时表此时正在发生或现阶段暂时的动作：She is working now.\n状态动词不用进行时：I know him(不说I am knowing him)。\nalways+进行时表抱怨：She is always complaining(她老是抱怨)。",("She usually drinks tea, but today she is drinking coffee.","她通常喝茶，但今天在喝咖啡。"),("The earth goes around the sun.","地球绕太阳转。"))
N("present_perfect_vs_past_simple","现在完成时vs一般过去时","完成时强调与现在联系，过去时强调过去发生","现在完成时(have/has+done)：强调过去动作对现在的影响或结果，不与具体过去时间连用。I have lost my key(现在还没找到)。\n一般过去时(V-ed)：强调过去某时发生的动作，常与具体过去时间连用。I lost my key yesterday(只说昨天丢了)。\n标志词：完成时用already/just/yet/ever/never；过去时用yesterday/last week/ago/in 2020。",("I have lived here for ten years.","我在这里住了十年。(现在还住)"),("I lived here in 2010.","2010年我住在这里。(现在不一定住)"))
N("past_simple_vs_past_continuous","一般过去vs过去进行","过去时表完成，进行时表当时正在发生","一般过去时：过去某时完成的动作或状态。I read a book last night.\n过去进行时：过去某时正在进行的动作。I was reading at 8 p.m. last night.\n常搭配使用：长动作(进行时)被短动作(过去时)打断。I was reading when the phone rang.\n并列进行时：While I was cooking, he was watching TV.",("I was watching TV when she called.","她来电时我在看电视。"),("I watched TV last night.","我昨晚看了电视。"))
N("past_perfect_vs_past_simple","过去完成时vs一般过去时","过去完成时表过去的过去，先于另一过去动作","过去完成时(had+done)：表示在过去某时之前已完成的动作，即'过去的过去'。\nWhen I arrived, the train had left.(火车先开走，我后到)\n对比：When I arrived, the train left.(我到了之后火车才开)\n标志词：by the time, before, after, when, by the end of。\n常用于间接引语中转述过去的事。",("When I arrived, the train had left.","我到时火车已经开走了。"),("She had finished before I came.","我来之前她已经完成了。"))
N("will_vs_be_going_to","will与be going to","will表即时决定/预测，be going to表计划/迹象","will：临时决定(I'll answer the phone)；客观预测(It will rain tomorrow)；意愿(I'll help you)。\nbe going to：已计划(I'm going to visit Paris)；有迹象的预测(Look at the clouds; it's going to rain)。\n区别：will侧重未来意愿或无迹象预测；be going to侧重已有计划或可见迹象。",("I'll answer the phone.","我去接电话。(临时决定)"),("I'm going to study abroad next year.","我明年要出国留学。(已计划)"))
N("present_perfect_vs_continuous","现在完成时vs完成进行时","完成时强调结果，完成进行时强调持续过程","现在完成时(have+done)：强调动作已完成或结果。I have read the book(读完了)。\n现在完成进行时(have been+Ving)：强调动作从过去持续到现在，可能继续。I have been reading for two hours(读了两小时，可能继续)。\n状态动词只用完成时：I have known him for years(不说have been knowing)。\nfor+时段，since+时间点。",("I have read three chapters.","我已读了三章。(完成)"),("I have been reading for two hours.","我已经读了两小时。(还在读)"))
N("state_verbs_not_progressive","状态动词不用进行时","know/like/understand等状态动词不用进行时","状态动词表心理/情感/拥有/感知，一般不用进行时：\n心理：know, understand, believe, think(认为), remember, forget。\n情感：like, love, hate, want, need, prefer。\n拥有：have, own, belong, possess。\n感知：see, hear, smell, taste, feel。\n其他：be, seem, appear, exist, consist。\n注意：有些词既可状态又可动作，意义不同：\nthink about(思考,可用进行时)vs think(认为,不用)；have(拥有,不用)vs have lunch(吃,可用)。",("I know the answer.","我知道答案。"),("I am thinking about the problem.","我正在思考这个问题。"))
N("tense_sequence_rules","时态呼应规则","主句和从句的时态需保持一致","时态呼应规则：\n1. 主句过去时，从句也用过去相关时态：He said he was tired. / He said he had finished.\n2. 主句现在/将来时，从句可用任何所需时态：I know he is/was/will be here.\n3. 客观真理从句用现在时：The teacher said the earth is round.\n4. 时间/条件状语从句中用现在时表将来：I'll call when I arrive.\n5. hope/wish后的从句按意义用时态。",("He said he would come.","他说他会来。"),("I'll tell him when he arrives.","他到时我会告诉他。"))
N("tense_in_time_clauses","时间状语从句中的时态","时间状语从句用现在时表将来(主将从现)","时间/条件状语从句中，用一般现在时表将来：\nI'll call you when I arrive.(不说will arrive)\nI won't go out if it rains tomorrow.\nAs soon as he comes, we'll start.\nBefore you leave, please lock the door.\nAfter he finishes his homework, he can play.\nUntil you return, I'll wait here.\n注意：主句用将来时(will)，从句用现在时。\n若强调完成，可用现在完成时：When I have finished, I'll tell you。",("I'll tell him when he comes back.","他回来时我会告诉他。"),("If it rains, we'll stay home.","如果下雨我们就待家。"))
N("tense_in_conditional","条件句中的时态","条件句分真实和非真实条件句，时态不同","真实条件句(Type 1)：If+现在时, 主句will+V。\nIf it rains, I will stay home.\n非真实条件句(Type 2)：If+过去时, 主句would+V。\nIf I were rich, I would travel.\n虚拟条件句(Type 3)：If+过去完成时, 主句would have+done。\nIf I had known, I would have helped.\n混合条件句：If+过去完成时, 主句would+V。\nIf I had studied harder, I would have a better job now.",("If it rains, I'll stay home.","如果下雨我就待家。"),("If I were you, I would go.","如果我是你，我会去。"))
N("present_simple_stative","一般现在时表状态","状态动词用一般现在时表当前状态","状态动词用一般现在时描述现在的状态：\nI know the answer. (不说am knowing)\nShe likes music. (不说is liking)\nHe owns a car.\nThis belongs to me.\nThe soup tastes delicious.\nI see a bird.\n注意：状态动词表持续状态而非动作，不用进行时。\n但表动作意义时可用进行时：I am tasting the soup(正在尝)。",("I understand the question.","我理解这个问题。"),("She loves chocolate.","她喜欢巧克力。"))
N("present_continuous_temporary","现在进行时表暂时","进行时可表现阶段暂时的动作或状态","现在进行时表现阶段暂时的情况：\nI'm living with my parents temporarily.\nShe's working at a cafe this summer.\nWe're studying French this semester.\nalways+进行时表抱怨/赞叹：He's always losing his keys.\nYou're always helping others.\n注意：进行时表暂时性，一般现在时表长期性。",("I'm living in Beijing this year.","今年我住在北京。"),("She's always losing her keys.","她老是丢钥匙。"))
N("past_simple_specific_time","一般过去时与具体时间","过去时强调过去某具体时间发生的动作","一般过去时常与具体过去时间标志词搭配：\nyesterday, last week/month/year, ago, in 2020, when I was young, just now, at that time。\nI saw him yesterday.\nShe graduated two years ago.\nThey moved here in 2018.\n注意：不能与现在完成时的时间标志词混用：\n×I have seen him yesterday. → I saw him yesterday.",("She visited Paris last summer.","她去年夏天去了巴黎。"),("I graduated three years ago.","我三年前毕业的。"))
N("present_perfect_unspecified","现在完成时与不明确时间","完成时不与具体过去时间连用，强调与现在的联系","现在完成时不与具体过去时间(yesterday, last week, in 2020等)连用：\nI have lost my keys(现在还没找到).\nHave you ever been to Japan?\nShe has just left.\nThey have already finished.\nI haven't done it yet.\n与不明确时间搭配：ever, never, already, just, yet, before, recently, so far, up to now, in the past few years。",("I have visited Japan twice.","我去过日本两次。"),("Have you ever eaten sushi?","你吃过寿司吗？"))
N("present_perfect_for_since","for与since的用法","for+时段，since+时间点，常与完成时搭配","for + 时段(多久)：for two hours, for ten years, for ages。\nsince + 时间点(自从何时)：since 2010, since Monday, since I was born, since last month。\n主句用现在完成时：I have lived here for ten years. / I have lived here since 2010.\n过去完成时：I had waited for two hours before he came。\n注意：for可省略：I've waited (for) two hours。",("She has studied English for five years.","她学了五年英语。"),("He has worked here since 2018.","他从2018年起在这里工作。"))
N("present_perfect_ever_never","ever与never","ever用于疑问表'曾经'，never表'从不'","ever用于疑问句/条件句/否定句表'曾经/在任何时候'：\nHave you ever been to Paris?\nIf you ever need help, call me.\nI don't think he has ever lied。\nnever表'从不/从未'：I have never been to Paris.\nalready用于肯定：I've already done it.\nyet用于否定/疑问：I haven't done it yet. / Have you done it yet?\njust表'刚刚'：She has just left.",("Have you ever been to China?","你去过中国吗？"),("I have never eaten snails.","我从没吃过蜗牛。"))
N("past_perfect_before_after","before/after与过去完成时","before/after可明确时间先后，可不强制用过去完成时","before和after已表明时间先后，过去完成时非必须：\nBefore I left, I (had) locked the door.\nAfter he (had) finished, he went home.\n但强调'先于'时用过去完成时：\nWhen I arrived, he had already left.\nBy the time I got there, the meeting had ended.\nby the time常引导过去完成时。",("Before I left, I had locked the door.","离开前我锁了门。"),("By the time I arrived, he had gone.","我到时他已经走了。"))
N("future_will_prediction","will表预测","will可对未来情况进行预测","will用于对未来预测：\nIt will rain tomorrow.\nYou'll love this movie.\nI think he will win.\n搭配：I think/I believe/I'm sure + will。\nwill be able to(将能够), will have to(将必须)。\nshall用于第一人称征求意见：Shall I open the window?\nShall we go now?",("I think it will rain tomorrow.","我觉得明天会下雨。"),("You'll love this book.","你会喜欢这本书的。"))
N("future_be_going_to_intention","be going to表意图","be going to表已计划的打算或意图","be going to表已经决定的计划/意图：\nI'm going to study medicine.\nThey're going to get married.\nWhat are you going to do this weekend?\n有迹象的预测：Look at the clouds; it's going to rain.\nbe about to do(即将做)：The movie is about to start.\nbe to do(预定做)：The President is to visit China.",("I'm going to learn Spanish next year.","我明年要学西班牙语。"),("The movie is about to start.","电影马上开始。"))
N("past_continuous_interrupted","过去进行时被打断","过去进行时常被一般过去时打断","过去进行时表正在进行的动作，被一般过去时的短动作打断：\nI was reading when the phone rang.\nWhile I was cooking, he came home.\nAs she was crossing the street, she saw an accident.\n两个同时进行的动作都用进行时：\nWhile I was cooking, he was watching TV.\n注意：when/while可互换，但while更强调同时性。",("I was sleeping when the alarm rang.","闹钟响时我在睡觉。"),("While I was cooking, the phone rang.","做饭时电话响了。"))
N("present_continuous_future","现在进行时表将来","进行时可表已安排好的将来计划","现在进行时可表已经安排好的将来计划：\nI'm meeting Tom tomorrow.\nShe's flying to London next week.\nWe're having a party on Saturday.\n常与将来时间搭配：tomorrow, next week, this weekend。\n适用于：go, come, leave, arrive, meet, see, have等动词。\n区别：be going to表意图；进行时表已安排好的具体计划。",("I'm meeting the boss at 3 p.m.","我下午三点见老板。"),("She's leaving for Paris tomorrow.","她明天动身去巴黎。"))
N("present_simple_future_timetable","一般现在时表将来","时刻表/日程表中用一般现在时表将来","按时间表/日程表发生的将来事件用一般现在时：\nThe train leaves at 8 a.m. tomorrow.\nThe flight takes off at 6 p.m.\nThe meeting starts at 3 o'clock.\n适用于：交通时刻表、电影/演出时间、会议日程、节日。\n注意：这是固定的计划安排，不因个人意愿改变。",("The train leaves at 8 a.m. tomorrow.","火车明早八点发车。"),("The movie starts at 7 p.m.","电影晚上七点开始。"))
N("tense_in_reported_speech","间接引语中的时态变化","转述他人话语时，时态需相应变化","间接引语中时态往过去推一级：\n一般现在→一般过去：He said he was tired.\n现在进行→过去进行：She said she was reading.\n现在完成→过去完成：He said he had finished.\n一般过去→过去完成：She said she had seen it.\nwill→would：He said he would come.\ncan→could, may→might, must→had to。\n注意：客观真理不变：He said the earth is round.\n今天转述也可不变时态：He said he is busy.",("He said he was tired.","他说他累了。"),("She said she would call me.","她说她会给我打电话。"))
N("tense_consistency","时态一致性","段落中时态应保持一致避免混乱","写作中时态应保持一致：\n叙述过去事件统一用过去时：Yesterday I went to the park. I saw many people. They were enjoying the sunshine.\n描述习惯/事实统一用现在时：She gets up at six. She exercises every morning.\n避免随意切换时态：×I went to school and see my friend. → I went to school and saw my friend.\n合理切换：描述不同时间的动作可以换时态。",("Yesterday I went to the park and saw many people.","昨天我去公园看到很多人。"),("She gets up early every day.","她每天早起。"))
N("passive_summary_rules","被动语态总则","被动语态构成be+过去分词，强调动作承受者","被动语态基本构成：be + 过去分词。\n各时态被动：\nam/is/are done(一般现在); was/were done(一般过去); will be done(将来); am/is/are being done(进行); have/has been done(完成); had been done(过去完成)。\n情态被动：can/must/should + be done。\n主动转被动：宾语→主语，动词→be+done，主语→by宾语。\n只有及物动词有被动。不及物动词(happen, arrive, occur)无被动。",("English is spoken all over the world.","全世界都说英语。"),("The house was built in 1990.","这房子建于1990年。"))
N("active_to_passive_rules","主动转被动规则","主动句宾语变主语，动词变被动，主语变by宾语","主动转被动步骤：\n1. 主动句的宾语变为被动句的主语。\n2. 主动句的谓语动词变为be+过去分词。\n3. 主动句的主语变为by短语(可省略)。\n例：They built the house. → The house was built by them.\n注意：\n- 双宾语动词有两个被动式：He gave me a book. → I was given a book. / A book was given to me.\n- 含宾补的被动：They elected him president. → He was elected president.\n- 短语动词被动不可拆开：They put off the meeting. → The meeting was put off.",("The cake was eaten by the boy.","蛋糕被男孩吃了。"),("She was given a present.","她收到了一份礼物。"))
N("passive_by_agent","被动语态中by的用法","by引出动作执行者，但常可省略","by短语引出动作执行者：\nThe book was written by Shakespeare.\nThe window was broken by a stone.\n省略by的情况：\n1. 不知执行者：My car was stolen.\n2. 执行者不重要：The bridge was built in 1990.\n3. 泛指人们：English is spoken in Canada.\n4. 明显的执行者：He was arrested.\n注意：with也可引出工具(非执行者)：He was killed with a knife. (knife是工具)",("The painting was painted by Picasso.","这幅画是毕加索画的。"),("My bike was stolen last night.","我的自行车昨晚被偷了。"))
N("passive_double_object","双宾语被动","give/send等双宾语动词的被动有两种形式","双宾语动词(give, send, show, tell, lend, offer, teach, pass, bring, hand)有两个被动形式：\n1. 间接宾语作主语：I was given a book. / She was offered a job.\n2. 直接宾语作主语(需加to/for)：A book was given to me. / A job was offered to her.\n常用第1种形式。\n注意：make/buy/get等用for不用to：A cake was made for her. (不说to her)",("She was given a present.","她收到了一份礼物。"),("A present was given to her.","一份礼物送给了她。"))
# === CLAUSE 硬编码 65条 ===
C("noun_clause_intro","名词性从句概述","that/if/whether/wh-引导的从句在句中作名词成分","名词性从句在句中起名词作用，可作主语、宾语、表语、同位语。\n引导词：that(无词义,引导陈述), if/whether(是否), wh-词(what/who/which/when/where/why/how)。\n语序：陈述语序(主语+谓语)，不用疑问语序。\n时态呼应：主句过去时，从句也用过去相关时态。\nthat在宾语从句中常可省略。",("What he said is true.","他说的是真的。"),("I don't know if he will come.","我不知道他是否会来。"))
C("noun_clause_that_subject","that引导主语从句","that从句作主语，that不可省略","that引导主语从句时that不可省略：\nThat she passed the exam is good news.\nThat he is honest is true.\n常用it作形式主语，that从句后移：\nIt is good news that she passed the exam.\nIt is true that he is honest.\nIt is important that we study hard.\nIt is a pity that he failed.",("That she passed the exam is good news.","她通过了考试是好消息。"),("It is important that we study hard.","努力学习很重要。"))
C("noun_clause_that_object","that引导宾语从句","that引导宾语从句，that常可省略","that引导宾语从句时that常可省略：\nI think (that) he is right.\nShe said (that) she was tired.\nHe told me (that) he would come.\n注意：\n- 两个that从句并列时第一个that可省，第二个不可省。\n- 介词后不用that从句(用it替代)：I'm sure of it that he will come.\n- 动词后跟多个宾语从句时只用一个that引导。",("I think that he is right.","我认为他是对的。"),("She said she was tired.","她说她累了。"))
C("noun_clause_that_predicative","that引导表语从句","that从句作表语，说明主语的内容","that引导表语从句：\nThe truth is that he lied.\nMy opinion is that we should go.\nThe problem is that we don't have enough money.\nThe reason is that he was ill.\n注意：because也可引导表语从句：The reason is because he was ill.(较口语) / The reason is that he was ill.(更规范)",("The truth is that he lied.","事实是他撒了谎。"),("The problem is that we have no money.","问题是我们没钱。"))
C("noun_clause_that_appositive","that引导同位语从句","that从句解释名词内容，that不省略","同位语从句解释名词(fact/news/idea/hope/truth/reason/suggestion等)的具体内容：\nThe news that he won the prize is exciting.\nThe fact that the earth is round is true.\nI have no idea that he was coming.\n注意：that在同位语从句中不充当成分，只起连接作用，不可省略。\n区别定语从句：that在同位语从句中不作成分，在定语从句中作主/宾语。",("The news that he won the prize is exciting.","他获奖的消息令人兴奋。"),("The fact that the earth is round is true.","地球是圆的这一事实是真的。"))
C("noun_clause_if_whether","if与whether引导从句","if/whether表'是否'，whether更正式可接or not","if和whether引导宾语从句表'是否'：\nI don't know if/whether he will come.\nwhether更正式，可用于主语从句/表语从句：\nWhether he will come is uncertain.\nwhether可接or not：I don't know whether he will come or not.\nwhether可接不定式：I don't know whether to go.\n注意：if引导从句不放句首(主语从句不用if)，whether可以。\n介词后只用whether：It depends on whether he comes。",("I don't know if he will come.","我不知道他是否会来。"),("Whether he will come is uncertain.","他是否会来还不确定。"))
C("noun_clause_wh_questions","wh-引导名词性从句","what/who/which/when/where/why/how引导从句","wh-词引导名词性从句，用陈述语序：\nWhat he said surprised me.(主语从句)\nI don't know where he lives.(宾语从句)\nThe question is how we can solve it.(表语从句)\nTell me when you will arrive.\nI wonder why he was late.\n注意：从句用陈述语序，不用疑问语序：\n×I don't know where is he. → I don't know where he is.",("What he said surprised me.","他说的话让我惊讶。"),("I don't know where he lives.","我不知道他住哪里。"))
C("noun_clause_exclamation","what/how引导感叹从句","what(a)+adj+n或how+adj/adv构成感叹","感叹句结构：\nWhat + (a/an) + 形容词 + 名词 + 主语 + 谓语!\nWhat a beautiful day it is!\nWhat delicious food you cooked!\nHow + 形容词/副词 + 主语 + 谓语!\nHow beautiful the flower is!\nHow fast he runs!\n注意：what修饰名词，how修饰形容词/副词。\n可省略主语和谓语：What a day! / How beautiful!",("What a beautiful day it is!","多美的一天啊！"),("How fast he runs!","他跑得真快！"))
C("noun_clause_it_formal","it作形式主语的从句","用it替代that/wh从句作形式主语","it作形式主语，真正主语在后：\nIt is important that we study hard.\nIt is said that he is rich.\nIt is a pity that she failed.\nIt seems that he is right.\nIt happened that I was there.\nIt is reported that the situation is improving.\n常用句型：It is + adj/名词 + that从句。\nIt takes + 时间 + to do.",("It is important that we study hard.","我们努力学习很重要。"),("It is said that he is rich.","据说他很富有。"))
C("noun_clause_word_order","名词性从句的语序","名词性从句用陈述语序，不用疑问语序","名词性从句必须用陈述语序(主语+谓语)：\n正确：I don't know where he lives.\n错误：I don't know where does he live.\n正确：Can you tell me what time it is?\n错误：Can you tell me what time is it?\n正确：I wonder why he was late.\n错误：I wonder why was he late?\n注意：wh-词在从句中充当成分(主/宾/表/状)，从句剩余部分按陈述语序排列。",("Can you tell me where he lives?","你能告诉我他住哪吗？"),("I don't know what he wants.","我不知道他想要什么。"))
C("noun_clause_tense_agreement","名词性从句的时态呼应","主句过去时从句也用过去相关时态","时态呼应规则：\n1. 主句现在/将来时，从句按实际情况用时态：I know he is/was/will be here.\n2. 主句过去时，从句用过去相关时态：He said he was tired. / He said he had finished.\n3. 客观真理不变：The teacher said the earth is round.\n4. 主句过去时但从句表将来也可用would：He said he would come.\n注意：could/would/might/should不受此限制。",("He said he was tired.","他说他累了。"),("I know he will come tomorrow.","我知道他明天会来。"))
C("noun_clause_common_patterns","名词性从句常见句型","名词性从句的常见固定句型","常见句型：\n1. That is why...(那就是为什么)：That is why he was late.\n2. The reason is that...(原因是)：The reason is that he was ill.\n3. It means that...(意味着)：It means that we have to start over.\n4. The fact is that...(事实是)：The fact is that we can't afford it.\n5. There is no doubt that...(毫无疑问)：There is no doubt that he is honest.\n6. It turns out that...(结果是)：It turns out that he was right.\n7. Chances are that...(可能)：Chances are that it will rain。",("That is why he was late.","那就是他迟到的原因。"),("There is no doubt that he is honest.","毫无疑问他是诚实的。"))
C("noun_clause_subject_verb","名词性从句主谓一致","名词性从句作主语时谓语用单数","名词性从句作主语时，谓语动词用单数：\nWhat he said is true.(不说are)\nThat she passed the exam is good news.\nWhether he will come is uncertain.\nWhat we need is more time.\n注意：what引导的主语从句，谓语可随表语变化：\nWhat we need are more books.(表语是books复数)\nWhat he gave me was a book.(表语是book单数)",("What he said is true.","他说的是真的。"),("What we need is more time.","我们需要的是更多时间。"))
C("noun_clause_reduced","名词性从句的简化","名词性从句可简化为不定式或动名词","名词性从句的简化：\n1. 宾语从句→不定式：I don't know what I should do. → I don't know what to do.\n2. 主语从句→不定式：When we should start is unclear. → When to start is unclear.\n3. whether从句→whether to do：I don't know whether I should go. → I don't know whether to go.\n4. that从句→动名词(表建议/要求)：I suggest that we leave now. → I suggest leaving now.\n注意：不是所有从句都能简化。",("I don't know what to do.","我不知道该怎么办。"),("I don't know whether to go.","我不知道是否该去。"))
C("noun_clause_special","名词性从句特殊用法","名词性从句的特殊情况和注意事项","特殊用法：\n1. that与what区别：that无词义不充当成分，what有词义充当成分。\n  I think that he is right.(that不充当成分) vs I know what he wants.(what作宾语)\n2. that从句不能作介词宾语：I'm interested in what he said.(不用that)\n3. doubt后用if/whether，not doubt后用that：I doubt if he will come. / I don't doubt that he will come.\n4. 同位语从句vs定语从句：that在同位语从句不充当成分，在定语从句充当成分。",("I'm interested in what he said.","我对他说的话感兴趣。"),("I doubt if he will come.","我怀疑他是否会来。"))
C("relative_clause_intro","定语从句概述","关系代词/副词引导定语从句修饰先行词","定语从句修饰名词(先行词)，由关系词引导。\n关系代词：who(人,主), whom(人,宾), whose(所属), which(物), that(人/物)。\n关系副词：when(时间), where(地点), why(原因)。\n限制性定语从句：无逗号，不可省略，影响句意。\n非限制性定语从句：有逗号，可省略，补充说明。\n关系词在从句中充当成分(主/宾/定/状)。",("The man who is talking is my father.","正在说话的人是我父亲。"),("The book that I bought is interesting.","我买的书很有趣。"))
C("relative_restrictive","限制性定语从句","无逗号隔开，不可省略，限定先行词范围","限制性定语从句紧跟先行词，无逗号，限定先行词的范围。\nThe man who lives next door is a doctor.(限定是哪个man)\nThe book that I bought is interesting.(限定是哪本书)\n可用that替代who/which。\n关系代词作宾语可省略：The book (that) I bought is interesting.\n先行词为物用that/which；为人用that/who。\n被最高级/序数词/the only修饰时常用that。",("The man who lives next door is a doctor.","住在隔壁的人是医生。"),("The book that I bought is interesting.","我买的书很有趣。"))
C("relative_non_restrictive","非限制性定语从句","有逗号隔开，可省略，补充说明先行词","非限制性定语从句用逗号与先行词隔开，补充说明，可省略不影响句意。\nMy father, who is a doctor, works hard.\nThe book, which I bought yesterday, is interesting.\n注意：\n- 不用that，用who/which。\n- 关系代词不可省略。\n- 可修饰整个句子：He passed the exam, which made his parents happy.\n- which可指代前文整句内容。",("My father, who is a doctor, works hard.","我父亲是医生，工作很努力。"),("He passed the exam, which made us happy.","他通过了考试，这让我们很高兴。"))
C("relative_pronoun_who","关系代词who/whom","who作主语，whom作宾语，修饰人","who(主格)：先行词为人，在从句中作主语。\nThe man who is standing there is my teacher.\nwhom(宾格)：在从句中作宾语，口语可省或用who替代。\nThe man (whom) I met yesterday is a doctor.\nwho/whom在限制性从句中可省略(作宾语时)。\nwhom在非限制性从句或介词后不省：The man to whom I spoke is a doctor.\n口语常用who替代whom。",("The man who is standing there is my teacher.","站在那里的人是我老师。"),("The man whom I met is a doctor.","我遇到的那个人是医生。"))
C("relative_pronoun_which","关系代词which","which修饰物，在从句中作主语或宾语","which修饰物(先行词为物)，作主语或宾语。\nThe book which is on the table is mine.(主语)\nThe book (which) I bought is interesting.(宾语,可省)\n非限制性从句中which可指代整个句子：\nHe failed the exam, which disappointed his parents.\nwhich在非限制性从句中不可省略，也不用that。\n介词+which：The house in which I live is old. = The house which I live in is old.",("The book which is on the table is mine.","桌上的书是我的。"),("He failed, which disappointed us.","他失败了，这让我们失望。"))
C("relative_pronoun_that","关系代词that","that可修饰人或物，只用于限制性从句","that可修饰人或物，只用于限制性定语从句。\nThe man that lives next door is a doctor.\nThe book that I bought is interesting.\n必须用that的情况：\n1. 先行词被最高级修饰：the best book that I've ever read。\n2. 先行词被序数词修饰：the first thing that he did。\n3. 先行词被the only/the very/just修饰：the only person that knows。\n4. 先行词既有人又有物：the man and his dog that...。\n5. 在疑问词who/which开头的句中：Who that knows him would say so?\n不用that：非限制性从句；介词后。",("This is the best book that I've ever read.","这是我读过的最好的书。"),("He is the only person that knows the truth.","他是唯一知道真相的人。"))
C("relative_pronoun_whose","关系代词whose","whose表所属关系，可修饰人或物","whose表所属关系，在从句中作定语。\n修饰人：The girl whose father is a teacher is my friend.\n修饰物：The book whose cover is red is mine. = The book the cover of which is red is mine.\nwhose既可修饰人也可修饰物。\n注意：whose + 名词 = the + 名词 + of which/whom。\nThe girl whose hair is long = The girl the hair of whom is long. (较正式)\nwhose不可省略。",("The girl whose father is a teacher is my friend.","父亲是老师的那个女孩是我朋友。"),("The book whose cover is red is mine.","封面是红色的那本书是我的。"))
C("relative_adverb_when","关系副词when","when引导定语从句修饰时间名词","when = 介词+which，修饰表示时间的先行词。\nI remember the day when I first met her. = on which\nThat was the year when he was born. = in which\nDo you know the time when the meeting starts?\n注意：when在从句中作时间状语，不作主/宾语。\nwhen可省略(限制性从句)：I'll never forget the day (when) we met.",("I remember the day when I first met her.","我记得第一次见她的那天。"),("That was the year when he was born.","那是他出生的那年。"))
C("relative_adverb_where","关系副词where","where引导定语从句修饰地点名词","where = 介词+which，修饰表示地点的先行词。\nThis is the house where I grew up. = in which\nThe city where she lives is beautiful.\nThis is the school where I studied.\n注意：where在从句中作地点状语。\nwhere可省略(限制性从句)：This is the place (where) we met.\n区别：where从句vs状语从句：This is the place where we met.(定语,修饰place) vs Where there is a will, there is a way.(状语)",("This is the house where I grew up.","这是我长大的房子。"),("The city where she lives is beautiful.","她住的城市很美。"))
C("relative_adverb_why","关系副词why","why引导定语从句修饰reason","why = for which，修饰先行词reason。\nThat is the reason why he was late. = for which\nI don't know the reason why she cried.\nThis is the reason why we must leave.\n注意：why在从句中作原因状语。\nwhy可省略：That is the reason (why) he was late.\nreason后可接that从句(同位语从句)：The reason that he was late is that he missed the bus.",("That is the reason why he was late.","那就是他迟到的原因。"),("I don't know the reason why she cried.","我不知道她为什么哭。"))
C("relative_prep","介词+关系代词","介词+which/whom结构，正式用法","介词+which(物)/whom(人)是正式用法。\nThe house in which I live is old. = which I live in\nThe man to whom I spoke is a doctor. = who I spoke to\n介词的选择取决于从句中的搭配：\nlive in the house → in which I live\nspeak to the man → to whom I spoke\ndepend on it → on which it depends\n注意：介词+that是错误的：×The house in that I live。",("The house in which I live is old.","我住的房子很旧。"),("The man to whom I spoke is a doctor.","我跟他说话的那个人是医生。"))
C("relative_omission","关系代词的省略","作宾语的关系代词在限制性从句中可省略","关系代词在限制性定语从句中作宾语时可省略：\nThe book (that/which) I bought is interesting.\nThe man (who/whom) I met is a doctor.\nThis is the house (that/which) I bought.\n不可省略的情况：\n1. 作主语：The man who lives next door is a doctor. (who不可省)\n2. 非限制性从句：My father, who is a doctor, works hard. (who不可省)\n3. 介词后：The man to whom I spoke. (whom不可省)\n4. whose不可省。",("The book I bought is interesting.","我买的书很有趣。"),("The man I met is a doctor.","我遇到的人是医生。"))
C("relative_that_vs_which","that与which的区别","限制性从句that可替代which，非限制性不用that","that与which的区别：\n1. 限制性从句中，that可替代which(物)：The book that/which I bought.\n2. 非限制性从句(有逗号)只能用which：My book, which is new, is interesting.\n3. 介词后只用which：The house in which I live. (不用that)\n4. 必须用that：先行词被最高级/序数词/the only修饰时。\n5. 必须用which：非限制性从句；指代整个句子。\n6. that可修饰人或物；which只修饰物。",("The book that I bought is new.","我买的书是新的。"),("My book, which is new, is interesting.","我的书是新的，很有趣。"))
C("relative_reduced","定语从句的简化","定语从句可简化为分词短语或介词短语","定语从句的简化：\n1. 简化为现在分词(主动)：The man who is standing there → The man standing there.\n2. 简化为过去分词(被动)：The book that was written by him → The book written by him.\n3. 简化为不定式(将to do)：The next train that will arrive → The next train to arrive.\n4. 简化为形容词：A book that is interesting → An interesting book.\n注意：进行时态的从句简化为现在分词；被动语态简化为过去分词；将来时简化为不定式。",("The man standing there is my teacher.","站在那里的人是我老师。"),("The book written by him is popular.","他写的书很受欢迎。"))
C("relative_as","关系代词as","as引导定语从句，可放句首，表'正如'","as引导定语从句，表'正如/像'，可放主句前或后。\nAs we all know, the earth is round.\nHe is from Australia, as is evident from his accent.\nThe same...as：the same book as mine(和我的同一本书)。\nsuch...as：such books as are on the shelf(书架上的那些书)。\n注意：as引导非限制性从句可放句首，which不可。\n常见：as is known to all, as has been mentioned, as expected。",("As we all know, the earth is round.","众所周知，地球是圆的。"),("He is from Australia, as is evident from his accent.","他是澳洲人，从口音就听得出来。"))
C("relative_but_what","关系代词but/what","but作关系代词表否定意义，what引导无先行词从句","but作关系代词(否定意义)：\nThere is no one but knows him. = who doesn't know him.\n(没有人不认识他)\nThere is no rule but has exceptions.\nwhat引导名词性关系从句(无先行词)：\nWhat you said is true. = The thing that you said is true.\nI don't understand what he means. = the thing that he means.\n注意：what不能引导定语从句(因为没有先行词)。",("There is no one but knows him.","没有人不认识他。"),("What you said is true.","你说的是真的。"))
C("relative_special","定语从句特殊用法","定语从句的特殊情况和注意事项","特殊用法：\n1. 关系代词作宾语可省略(限制性从句)：The book I bought is new.\n2. 介词+关系代词：The house in which I live is old.\n3. whose+名词=of which/whom+名词：The book whose cover is red = the cover of which is red.\n4. 关系词指代整个句子(非限制性)：He failed, which made us sad.\n5. 分隔定语从句：The man is here who called you yesterday.\n6. 定语从句vs同位语从句：The news that he won (同位语,that不充当成分) vs The news that he told me (定语,that作宾语)。",("He failed, which made us sad.","他失败了，这让我们难过。"),("The news that he won is exciting.","他获胜的消息令人兴奋。"))
C("adverbial_time_as_soon_as","时间状语从句as soon as","as soon as表'一…就'，引导时间状语从句","as soon as引导时间状语从句，表'一…就'：\nAs soon as I arrived, I called him.\nI'll tell him as soon as he comes.\n类似结构：\nthe moment/minute/instant + 从句 = 一…就。\nThe moment I saw her, I knew she was the one.\nHardly...when / No sooner...than(倒装)：\nNo sooner had I arrived than the phone rang.\nHardly had I sat down when the bell rang.",("As soon as I arrived, I called him.","我一到就给他打电话。"),("I'll tell him as soon as he comes.","他一来我就告诉他。"))
C("adverbial_time_once","时间状语从句once","once表'一旦'，引导时间/条件状语从句","once引导从句，表'一旦'，兼有时间和条件意义：\nOnce you start, you can't stop.\nOnce he arrives, we'll begin.\nOnce you understand the rule, it's easy.\n注意：once引导的从句用现在时表将来：Once he comes, we'll start.\n类似：as long as(只要), whenever(每当), now that(既然)。",("Once you start, you can't stop.","一旦开始就停不下来。"),("Once he arrives, we'll begin.","他一到我们就开始。"))
C("adverbial_reason_since","原因状语从句since/as","since/as表原因，语气比because弱","since/as引导原因状语从句，语气比because弱。\nsince(既然)：Since you are here, let's start.\nas(因为)：As it was raining, we stayed home.\n区别：\n- because：回答why提问，语气最强，可放主句后。\n- since/as：已知原因，语气弱，常放句首。\n- for：补充原因，不放句首，语气最弱。\nnow that(既然)：Now that you're here, help me.",("Since you are here, let's start.","既然你来了，我们开始吧。"),("As it was raining, we stayed home.","因为下雨我们待家。"))
C("adverbial_concession_even_if","让步状语从句even if/even though","even if/though表'即使'，引导让步从句","even if和even though引导让步状语从句，表'即使/尽管'：\nEven if it rains, I'll go out.\nEven though he was tired, he kept working.\n区别：\n- even if：假设性让步(可能不发生)：Even if it rains tomorrow, I'll go.\n- even though：事实性让步(已发生)：Even though it was raining, he went out.\n类似：though, although, while(虽然)。",("Even if it rains, I'll go out.","即使下雨我也要出去。"),("Even though he was tired, he kept working.","尽管累了，他继续工作。"))
C("adverbial_concession_while","让步状语从句while","while可表'虽然/尽管'，引导让步从句","while引导让步从句，表'虽然/尽管'：\nWhile I understand your point, I disagree.\nWhile he is clever, he is lazy.\n注意：while有多种意义：\n1. 当…时(时间)：While I was reading, he called.\n2. 虽然/尽管(让步)：While I agree, I have concerns.\n3. 然而/而(对比)：I like tea, while he likes coffee.\n根据语境判断意义。",("While I understand your point, I disagree.","虽然我理解你的观点，但我不同意。"),("I like tea, while he likes coffee.","我喜欢茶，而他喜欢咖啡。"))
C("adverbial_condition_as_long_as","条件状语从句as long as","as long as/provided that表'只要'","as long as和provided/providing that引导条件从句，表'只要'：\nAs long as you try, you can succeed.\nYou can borrow it provided that you return it tomorrow.\n类似结构：\non condition that(条件是)\nin case(万一)\nunless(除非) = if...not\n注意：条件从句用现在时表将来：As long as you come, I'll wait.",("As long as you try, you can succeed.","只要你尝试，就能成功。"),("You can borrow it provided that you return it.","你可以借，前提是还回来。"))
C("adverbial_condition_in_case","条件状语从句in case","in case表'万一/以防'，引导条件从句","in case引导从句，表'万一/以防'：\nTake an umbrella in case it rains.\nI'll write it down in case I forget.\n注意：in case从句中常用should(较正式)或现在时/过去时：\nIn case it should rain, take an umbrella.\nin case of + 名词：In case of fire, call 119.\n区别：in case(以防万一) vs if(如果)。",("Take an umbrella in case it rains.","带把伞以防下雨。"),("I'll write it down in case I forget.","我记下来以防忘记。"))
C("adverbial_purpose_in_order","目的状语从句in order that","in order that/so that表目的，从句含can/will","in order that和so that引导目的状语从句：\nI got up early so that I could catch the train.\nHe spoke loudly in order that everyone could hear.\n从句中通常含can/could/will/would/may/might等情态动词。\n否定形式：so that...won't/in order that...may not。\n简化为不定式：so as to do / in order to do。\nI got up early in order to catch the train.",("I got up early so that I could catch the train.","我早起以便赶上火车。"),("He spoke loudly so everyone could hear.","他大声说以便大家都能听到。"))
C("adverbial_result_such","结果状语从句such...that","such+(a/an)+adj+n+that表'如此…以至于'","such...that引导结果状语从句：\nsuch + (a/an) + 形容词 + 名词 + that从句。\nIt was such a hot day that we stayed home.\nHe is such a clever boy that everyone likes him.\n与so...that的区别：\nso + 形容词/副词 + that：so hot that we stayed home.\nsuch + 名词短语 + that：such a hot day that...\nso + 形容词 + a/an + 名词：so hot a day that...(正式)\nsuch that(结果是)：His anger was such that he couldn't speak。",("It was such a hot day that we stayed home.","天气太热了，我们待在家。"),("He is such a clever boy that everyone likes him.","他如此聪明，大家都喜欢他。"))
C("adverbial_manner_as_if","方式状语从句as if/though","as if/though表'仿佛/好像'，可接虚拟语气","as if和as though引导方式状语从句，表'仿佛/好像'：\nHe looks as if he were ill.(虚拟,实际上没病)\nHe looks as if he is ill.(直陈,可能真病了)\nIt seems as though it will rain.\n注意：\n- 表与现在事实相反用过去时(were)：He talks as if he knew everything.\n- 表与过去事实相反用过去完成时：He looks as if he had seen a ghost.\n- as if后可接不定式：He opened his mouth as if to speak。",("He looks as if he were ill.","他看起来好像生病了。"),("She talks as if she knew everything.","她说话好像什么都知道。"))
C("adverbial_comparison_as","比较状语从句as...as","as...as表同级比较，not as/so...as表不如","as...as引导比较状语从句：\nHe runs as fast as his brother does.\nShe is as tall as her mother.\n否定形式：not as/so...as。\nHe doesn't run as fast as his brother.\n倍数：twice as...as, three times as...as。\nThis room is twice as big as that one.\n注意：第一个as后接形容词/副词原级。",("He runs as fast as his brother.","他和弟弟跑得一样快。"),("This room is twice as big as that one.","这个房间是那个两倍大。"))
C("adverbial_concession_no_matter","让步状语从句no matter","no matter what/who/how表'无论…'","no matter + wh-词引导让步从句，表'无论…'：\nNo matter what happens, I'll support you.\nNo matter how hard he tried, he failed.\nNo matter where you go, I'll follow.\n= whatever/whoever/however/wherever：\nWhatever happens, I'll support you.\nHowever hard he tried, he failed.\n注意：no matter what侧重让步(无论什么)；whatever可引导名词性从句。",("No matter what happens, I'll support you.","无论发生什么，我都支持你。"),("However hard he tried, he failed.","无论多努力，他都失败了。"))
C("direct_indirect_intro","直接引语与间接引语概述","直接引语加引号原话转述，间接引语用自己的话转述","直接引语：原话加引号。She said, 'I am tired.'\n间接引语：用自己的话转述。She said that she was tired.\n转换要点：\n1. 去引号加that(陈述句)。\n2. 人称变化：I→he/she, my→his/her。\n3. 时态变化：往过去推一级。\n4. 时间/地点词变化：now→then, today→that day, here→there。\n5. 指示词变化：this→that, these→those。\n6. 疑问句语序变陈述语序。",("She said, 'I am tired.'","她说：'我累了。'"),("She said that she was tired.","她说她累了。"))
C("direct_indirect_statements","间接引语陈述句","直接陈述句转间接引语需变人称、时态、时间词","陈述句的转换：\n1. 人称变化：I→he/she, we→they, my→his/her。\n   He said, 'I lost my key.' → He said that he had lost his key.\n2. 时态变化(主句过去时)：\n   一般现在→一般过去：am→was, work→worked。\n   现在进行→过去进行：am reading→was reading。\n   现在完成→过去完成：have done→had done。\n   一般过去→过去完成：did→had done。\n   will→would, can→could, may→might, must→had to。",("He said, 'I am tired.'","他说：'我累了。'"),("He said that he was tired.","他说他累了。"))
C("direct_indirect_questions","间接引语疑问句","疑问句转间接引语用if/whether或wh-词，语序变陈述","疑问句的转换：\n1. 一般疑问句→if/whether：\n   He asked, 'Are you ready?' → He asked if/whether I was ready.\n2. 特殊疑问句→wh-词：\n   She asked, 'Where do you live?' → She asked where I lived.\n3. 语序变陈述语序(主语+谓语)：\n   ×She asked where did I live. → She asked where I lived.\n4. 疑问词作主语时语序不变：\n   He asked, 'Who is there?' → He asked who was there.\n5. 时态/人称变化同陈述句。",("He asked, 'Do you like tea?'","他问：'你喜欢茶吗？'"),("He asked if I liked tea.","他问我是否喜欢茶。"))
C("direct_indirect_commands","间接引语祈使句","祈使句转间接引语用tell/ask sb to do结构","祈使句的转换：\n1. 肯定祈使句→to do：\n   He said, 'Open the door.' → He told me to open the door.\n   She said, 'Please sit down.' → She asked me to sit down.\n2. 否定祈使句→not to do：\n   He said, 'Don't smoke.' → He told me not to smoke.\n3. 引导动词变化：\n   tell sb to do(告诉), ask sb to do(请), order sb to do(命令), advise sb to do(建议), warn sb to do(警告)。\n4. Let's→suggest doing/suggest that：\n   He said, 'Let's go.' → He suggested going. / He suggested that we go.",("He told me to open the door.","他让我开门。"),("She asked me not to smoke.","她让我别抽烟。"))
C("direct_indirect_time_place","间接引语时间地点词变化","now→then, today→that day, here→there等变化","时间/地点/指示词的变化：\nnow→then, today→that day, tonight→that night。\nyesterday→the day before/the previous day。\ntomorrow→the next day/the following day。\nthis week→that week, last week→the week before。\nago→before, here→there, this→that, these→those。\ncome→go, bring→take。\n例：He said, 'I'll come here tomorrow.' → He said that he would go there the next day.\n注意：当天转述今天的事，时间词不变。",("He said, 'I came yesterday.'","他说：'我昨天来的。'"),("He said he had come the day before.","他说他前一天来的。"))
C("direct_indirect_modal","间接引语情态动词变化","can→could, may→might, must→had to等变化","情态动词的变化(主句过去时)：\ncan→could: He said, 'I can swim.' → He said he could swim.\nmay→might: She said, 'I may come.' → She said she might come.\nmust→had to: He said, 'I must go.' → He said he had to go.\nwill→would: She said, 'I will help.' → She said she would help.\nshall→should: He said, 'I shall return.' → He said he should return.\n注意：\n- could/would/might/should/ought to不变。\n- must表推测时不变：He said it must be true.\n- had better不变：She said I had better go.",("He said he could swim.","他说他会游泳。"),("She said she had to go.","她说她得走了。"))
C("direct_indirect_special","间接引语特殊用法","间接引语的特殊情况和注意事项","特殊用法：\n1. 客观真理不变：He said the earth is round.\n2. 当天转述不变时态：He said he is busy today.\n3. 过去完成时不变：He said he had finished.\n4. could/would/might/should不变。\n5. 引导动词多样：explain, admit, deny, suggest, promise, complain, warn。\n   He admitted that he was wrong.\n   She denied having seen him.\n   He promised to help me.\n6. 间接疑问句vs直接疑问句：I wonder where he lives.(间接) vs Where does he live?(直接)\n7. 自由间接引语(无引导词)：He was tired. He wanted to go home。",("He admitted that he was wrong.","他承认他错了。"),("She promised to help me.","她答应帮我。"))
C("relative_prep_end","关系代词放句末","介词可放从句末，关系代词省略","介词可放在从句末尾，此时关系代词用that/who/which或省略：\nThe house (that) I live in is old. = The house in which I live is old.\nThe man (who) I spoke to is a doctor. = The man to whom I spoke is a doctor.\n口语中常用介词放句末并省略关系代词。\n正式书面语中介词放关系代词前。",("The book I'm reading is good.","我在读的书不错。"),("The man I spoke to left.","我说话的那个人走了。"))
C("relative_sentential","关系词指代整句","which可指代整个主句内容","非限制性定语从句中which可指代整个前句：\nHe passed the exam, which made his parents happy.\nShe came late, which annoyed the teacher.\nHe said nothing, which was wise.\n注意：that不能指代整句。\nas也可指代整句：As is known to all, he is honest.\n区别：which放主句后；as可放主句前或后。",("He passed, which made us happy.","他通过了，这让我们高兴。"),("As is known to all, he is honest.","众所周知他诚实。"))
C("relative_quantifier","关系代词前加量词","关系代词前可加数词/量词修饰","关系代词前可加数量词：\nI have three books, two of which are novels.\nHe has many friends, some of whom are doctors.\nThe team has ten members, most of whom are young.\n结构：名词/代词 + of + which/whom。\n也可用whose+名词替代：the books whose covers are red。",("I have three books, two of which are novels.","我有三本书，其中两本是小说。"),("He has many friends, some of whom are doctors.","他有很多朋友，有些是医生。"))
C("adverbial_where_wherever","地点状语从句wherever","wherever表'无论哪里'，引导让步地点从句","wherever引导地点/让步状语从句：\nWherever you go, I'll follow you.\nSit wherever you like.\nWherever there is water, there is life.\n类似：everywhere, anywhere。\n注意：wherever可表地点(任何地方)或让步(无论哪里)。\n=no matter where。",("Wherever you go, I'll follow.","无论你去哪，我都跟随。"),("Sit wherever you like.","随便坐。"))
C("adverbial_concession_though_as","让步as/though倒装","as/though引导让步从句可倒装","as和though引导让步从句时可倒装(表强调)：\n1. 形容词/副词/名词 + as + 主语 + 谓语：\n   Tired as he was, he kept working.(=Although he was tired)\n   Child as he is, he knows a lot.\n2. 动词原形 + as + 主语 + 助动词：\n   Try as he might, he failed.\n注意：名词提前时不加冠词：Child as he is(不说A child as he is)。\nthough也可这样用，但although不可以。",("Tired as he was, he kept working.","虽然累了，他继续工作。"),("Child as he is, he knows a lot.","虽然还是孩子，他知道很多。"))
C("adverbial_purpose_negative","否定目的状语从句","so that...not/in order that...not表否定目的","否定目的从句：\nHe spoke loudly so that everyone could hear.\nHe whispered so that no one could hear.(否定目的)\n= He whispered in order that no one should hear.\n也可用lest(以免)：He ran lest he should miss the train.\nlest后常用should(虚拟语气)。\nfor fear that(生怕)：He left early for fear that he might be late.",("He whispered so that no one could hear.","他低声说以免有人听到。"),("He ran lest he should miss the train.","他跑以免错过火车。"))
C("noun_clause_whether_infinitive","whether+to do","whether后可接不定式表'是否要'","whether后接不定式：\nI don't know whether to go or stay.\nShe wondered whether to accept the offer.\nI can't decide whether to buy it.\n注意：if后不接不定式，只有whether可以。\nwhat/where/when/how等也可接不定式：\nI don't know what to do.\nShe doesn't know where to go.\nI forget how to do it.",("I don't know whether to go.","我不知道是否该去。"),("She doesn't know what to do.","她不知道该怎么办。"))
C("noun_clause_doubt","doubt后的名词性从句","doubt后用if/whether，not doubt后用that","doubt后引导词规则：\n1. 肯定句doubt后用if/whether：I doubt if he will come.\n2. 否定句/疑问句后用that：I don't doubt that he will come. / Do you doubt that he will come?\n类似：sure/certain后用that；not sure后用if/whether。\nI'm sure that he is right. / I'm not sure if he is right.\n注意：there is no doubt that...用that。",("I doubt if he will come.","我怀疑他是否会来。"),("There is no doubt that he is honest.","毫无疑问他诚实。"))
C("relative_double","双重定语从句","一个先行词可被两个定语从句修饰","双重定语从句：\nThe man who is standing there and who is wearing a blue suit is my teacher.\n注意：\n1. 两个从句用and/or/but连接。\n2. 第二个从句的关系词不可省略。\n3. 两个从句分别修饰同一先行词。\n4. 也可分别修饰不同方面：The book that I bought which is about history is interesting.",("The man who is tall and who is wearing glasses is my teacher.","又高又戴眼镜的那个人是我老师。"),("This is the book that I bought which is about history.","这是我买的关于历史的书。"))
C("relative_which_sentential","which指代整句详述","which在非限制性从句中可指代前文整句内容","which指代整个前句的用法详述：\nHe came late, which annoyed the teacher.(which=他迟到这件事)\nShe smiled, which was rare.(which=她微笑这件事)\nHe refused to help, which surprised everyone.\n注意：\n- which指代整句时用单数谓语。\n- 不能用that替代。\n- 可加限定词：He failed, at which point he gave up.\n- in which case, by which time等固定搭配。",("He came late, which annoyed the teacher.","他迟到了，这让老师生气。"),("She smiled, which was rare.","她笑了，这很少见。"))
C("adverbial_result_so_detail","结果状语从句so...that详述","so+adj/adv+that表'如此…以至于'","so...that引导结果从句：\nso + 形容词/副词 + that从句。\nIt was so cold that I shivered.\nHe spoke so fast that I couldn't understand.\nso + 形容词 + a/an + 名词 + that：so beautiful a day that...\nso that(以便/结果是)：I got up early so that I could catch the train.\nso as to(以便)：I got up early so as to catch the train.\nso...as to(如此…以至于)：He was so kind as to help me.",("It was so cold that I shivered.","太冷了我发抖。"),("He spoke so fast that I couldn't follow.","他说得太快我跟不上。"))
C("direct_indirect_exclamatory","间接引语感叹句","感叹句转间接引语用what/how引导","感叹句的转换：\nHe said, 'What a beautiful day!' → He exclaimed what a beautiful day it was.\nShe said, 'How wonderful!' → She exclaimed how wonderful it was.\n注意：\n1. 引导词用what/how保留。\n2. 时态和人称变化同陈述句。\n3. 引导动词可用exclaim, say等。\n4. 感叹词(oh, ah等)省略。",("He exclaimed what a beautiful day it was.","他感叹多美的一天。"),("She said how wonderful it was.","她说多棒啊。"))
C("direct_indirect_mixed","混合间接引语","多种类型混合的间接引语转换","混合类型的间接引语：\n1. 陈述+疑问：He said he was tired and asked if I was too.\n2. 陈述+祈使：She said she was busy and told me to wait.\n3. 混合人称/时态：He told me that he had seen her yesterday and that she was fine.\n注意：\n- 各部分分别按类型转换。\n- 保持人称和时态的一致性。\n- 常用and/but连接各部分。",("He said he was tired and asked if I could help.","他说他累了并问我能否帮忙。"),("She said she was busy and told me to wait.","她说她忙让我等。"))
# === ADVANCED 硬编码 70条 ===
A("subjunctive_wish","虚拟语气wish","wish+过去时表与现在相反愿望，wish+过去完成时表与过去相反","wish引导虚拟语气：\n1. wish + 过去时(与现在相反)：I wish I were rich.\n2. wish + 过去完成时(与过去相反)：I wish I had studied harder.\n3. wish + would/could(与将来相反/希望)：I wish you would stop talking.\n注意：wish表难以实现的愿望；hope表可能实现：I hope you can come.\nwere不分人称：I wish I were/I wish she were.",("I wish I were taller.","我希望我更高。"),("I wish I had studied harder.","我真希望我当时更努力。"))
A("subjunctive_if_only","if only虚拟","if only+虚拟语气表强烈愿望或遗憾","if only引导虚拟语气，表'要是…就好了'：\n1. if only + 过去时(现在)：If only I knew the answer!\n2. if only + 过去完成时(过去)：If only I had listened to you!\n3. if only + would(将来)：If only it would stop raining!\n比wish语气更强，常单独成句。\nif only和I wish可互换，但if only更强调感情。",("If only I knew the answer!","要是我知道答案就好了！"),("If only I had listened to you!","要是我听了你的话就好了！"))
A("subjunctive_as_if","as if虚拟","as if/though后用虚拟语气表与事实相反","as if/though后接虚拟语气表非真实情况：\n1. 过去时(与现在相反)：He talks as if he knew everything.\n2. 过去完成时(与过去相反)：He looks as if he had seen a ghost.\n注意：如果可能为真，不用虚拟：\nHe looks as if he is ill.(可能真病了)\nHe talks as if he were the boss.(实际上不是)\nwere用于所有人称(正式)。",("He talks as if he knew everything.","他说话好像什么都知道。"),("She looks as if she had seen a ghost.","她看起来好像见了鬼。"))
A("subjunctive_would_rather","would rather虚拟","would rather+过去时表宁愿他人做某事","would rather的虚拟用法：\n1. would rather + 动词原形(自己)：I would rather stay home.\n2. would rather + 过去时(他人)：I would rather you didn't smoke.\n3. would rather + 过去完成时(过去)：I would rather you hadn't said that.\n注意：\n- would rather do than do：I'd rather walk than take a bus.\n- would rather后接从句用虚拟语气。\n- 主语与would rather之间用'd缩写。",("I would rather stay home.","我宁愿待家。"),("I would rather you didn't smoke.","我希望你别抽烟。"))
A("subjunctive_it_is_time","it is (high) time虚拟","it is time+过去时表'该做某事了'","it is (high/about) time + 过去时(虚拟)：\nIt is time we went home.\nIt is high time you stopped smoking.\nIt is about time she found a job.\n注意：\n- 用过去时表虚拟(现在该做但还没做)。\n- 也可接to do：It is time to go home.\n- 区别：It is time we went(虚拟,强调该做了) vs It is time for us to go(不定式)。",("It is time we went home.","我们该回家了。"),("It is high time you stopped smoking.","你该戒烟了。"))
A("subjunctive_demand","suggest类动词虚拟","suggest/demand/insist等后用(should)+动词原形","suggest类动词后的虚拟语气：\n动词：suggest, demand, insist, require, request, order, propose, advise, recommend, urge。\n结构：主语 + (should) + 动词原形。\nHe suggested that we (should) leave early.\nShe demanded that he apologize.\nThe doctor advised that he take a rest.\n注意：should可省略(美式常省)。\n否定：suggest that he (should) not go.\n被动：It is suggested that he (should) be punished.",("He suggested that we leave early.","他建议我们早点走。"),("She insisted that he apologize.","她坚持要他道歉。"))
A("subjunctive_adjective","形容词后虚拟","essential/important/necessary等后用虚拟","形容词后的虚拟语气：\nIt is + 形容词 + that + (should) + 动词原形。\n形容词：essential, important, necessary, vital, crucial, imperative, urgent, desirable, advisable。\nIt is essential that everyone (should) be informed.\nIt is important that he (should) arrive on time.\nIt is necessary that she (should) take the medicine.\nIt is imperative that we (should) act now.\nshould可省略。",("It is essential that everyone be informed.","每个人都要被通知到。"),("It is important that he arrive on time.","他按时到很重要。"))
A("subjunctive_condition_1","真实条件句Type 1","If+现在时,主句will+V表可能发生的条件","Type 1真实条件句：\nIf + 一般现在时, 主句 + will/won't + 动词原形。\nIf it rains, I will stay home.\nIf you study hard, you will pass.\nIf he comes, I'll tell him.\n注意：\n- 表可能发生的条件。\n- 从句用现在时(主将从现)。\n- 可用can/may/should/must替代will。\n- 除非unless = if...not：Unless you hurry, you'll be late.",("If it rains, I'll stay home.","如果下雨我就待家。"),("If you study hard, you'll pass.","努力学习就能通过。"))
A("subjunctive_condition_2","非真实条件句Type 2","If+过去时,主句would+V表与现在相反的假设","Type 2非真实条件句(与现在相反)：\nIf + 一般过去时, 主句 + would/could/might + 动词原形。\nIf I were rich, I would travel the world.\nIf I had time, I would help you.\nIf she knew, she would tell us.\n注意：\n- were用于所有人称(正式)。\n- 表与现在事实相反的假设。\n- If I were you, I would...(常用建议句型)。",("If I were rich, I would travel.","如果我有钱，我会去旅行。"),("If I were you, I would go.","如果我是你，我会去。"))
A("subjunctive_condition_3","虚拟条件句Type 3","If+过去完成时,主句would have+done表与过去相反","Type 3虚拟条件句(与过去相反)：\nIf + 过去完成时, 主句 + would/could/might + have + 过去分词。\nIf I had known, I would have helped.\nIf she had studied, she would have passed.\nIf it hadn't rained, we would have gone out.\n注意：\n- 表与过去事实相反的假设。\n- 常表遗憾：If only I had..., I would have...\n- 省略if需倒装：Had I known, I would have helped.",("If I had known, I would have helped.","如果我知道，我会帮忙的。"),("If she had studied, she would have passed.","如果她学了，就会通过的。"))
A("subjunctive_mixed","混合条件句","条件与结果分属不同时间","混合条件句(条件与结果时间不同)：\n1. 过去条件+现在结果：If I had studied harder, I would have a better job now.\n2. 现在条件+过去结果：If I were more careful, I wouldn't have made that mistake.\n注意：\n- 根据实际意义选择时态。\n- 条件和结果可以分属不同时间。\n- 常用now, then等时间词明确时间。",("If I had studied harder, I would have a better job now.","如果我更努力学习，现在就有更好的工作。"),("If I were rich, I would have bought it.","如果我有钱，我就买了。"))
A("subjunctive_inversion","虚拟条件句倒装","省略if时had/were/should提前倒装","虚拟条件句省略if时倒装：\n1. had提前(Type 3)：Had I known, I would have helped. = If I had known...\n2. were提前(Type 2)：Were I rich, I would travel. = If I were rich...\n3. should提前(Type 1,较正式)：Should it rain, I would stay. = If it should rain...\n注意：\n- 只有had/were/should可提前。\n- if省略后主语和助动词倒装。\n- 用于正式书面语。",("Had I known, I would have helped.","如果我知道，我会帮忙。"),("Were I rich, I would travel.","如果我有钱，我会去旅行。"))
A("subjunctive_without_but_for","without/but for虚拟","without/but for + 名词引出虚拟条件","without和but for引出虚拟条件：\nWithout your help, I would have failed. = If you hadn't helped me.\nBut for the rain, we would have gone out.\nBut for your advice, I would have made a mistake.\n类似：but that(若非)：But that I saw it, I wouldn't have believed it.\n注意：without/but for后接名词，不接从句。\n根据语境用would do(现在)或would have done(过去)。",("Without your help, I would have failed.","没有你的帮助，我就失败了。"),("But for the rain, we would have gone out.","要不是下雨，我们就出去了。"))
A("phrasal_verb_separable","可分短语动词","可分短语动词的宾语可放中间或后面","可分短语动词(catch词可分开)：\n1. 宾语是名词：可放中间或后面。Turn on the light. = Turn the light on.\n2. 宾语是代词：必须放中间。Turn it on. (不说Turn on it.)\n3. 常见可分短语动词：turn on/off, put on, take off, pick up, look up, give up, try on, put off, throw away。\n注意：代词宾语必须放中间。",("Turn on the light.","开灯。"),("Turn it on.","把它打开。"))
A("phrasal_verb_inseparable","不可分短语动词","不可分短语动词的宾语放后面，不可拆开","不可分短语动词(不能分开)：\n1. 宾语放后面，不可放中间。\n2. 常见不可分短语动词：look for, look after, listen to, wait for, belong to, depend on, rely on, insist on, consist of, look at。\n3. 代词宾语也放后面：Look for it. (不说Look it for.)\n4. 三词短语动词不可分：look forward to, put up with, get along with, run out of。",("I'm looking for my keys.","我在找钥匙。"),("She looks after the children.","她照顾孩子。"))
A("phrasal_verb_common","常见短语动词搭配","常用短语动词及其意义","常见短语动词：\ngive up(放弃), take off(起飞/脱下), look up(查阅), put off(推迟), pick up(捡起/接人), turn down(拒绝/调小), work out(锻炼/解决), figure out(弄明白), get along(相处), break down(出故障), bring up(抚养), come across(偶遇), set up(建立), carry on(继续), look forward to(期待)。",("Don't give up on your dreams.","不要放弃梦想。"),("I look forward to seeing you.","我期待见到你。"))
A("verb_pattern_v_to_do","接不定式的动词","want/decide/hope等后接to do","接不定式(to do)的动词：\nwant, decide, hope, plan, agree, promise, refuse, offer, manage, fail, choose, expect, wish, learn, pretend, seem, appear, happen, afford, determine, threaten。\nI decided to leave. / She hopes to win. / He promised to help.\n不定式完成式：He seems to have left. / She is said to be rich.",("I decided to leave early.","我决定早点走。"),("She hopes to win the prize.","她希望能获奖。"))
A("verb_pattern_v_doing","接动名词的动词","enjoy/finish/mind等后接doing","接动名词(doing)的动词：\nenjoy, finish, mind, practice, avoid, suggest, consider, keep, stop, deny, admit, imagine, risk, miss, postpone, resist, appreciate, delay, involve, escape。\nI enjoy reading. / She finished cooking. / Would you mind closing the door?\n注意：stop doing(停止做) vs stop to do(停下来去做)。",("I enjoy reading novels.","我喜欢读小说。"),("Would you mind closing the door?","介意关门吗？"))
A("verb_pattern_v_both","既接to do又接doing的动词","remember/forget/stop等接to do和doing意义不同","意义不同的动词：\n1. remember to do(记得要做) vs remember doing(记得做过)。\n   Remember to lock the door. / I remember locking the door.\n2. forget to do(忘记要做) vs forget doing(忘记做过)。\n   Don't forget to call. / I'll never forget meeting her.\n3. stop to do(停下来去做) vs stop doing(停止做)。\n   He stopped to smoke. / He stopped smoking.\n4. try to do(努力做) vs try doing(试着做)。\n   Try to open it. / Try opening it.\n5. regret to do(遗憾要做) vs regret doing(后悔做过)。\n   I regret to tell you... / I regret telling you.",("Remember to lock the door.","记得锁门。"),("I remember locking the door.","我记得锁了门。"))
A("verb_pattern_v_object_to_do","接宾语+不定式","tell/ask/want sb to do","接宾语+不定式的动词：\ntell, ask, want, order, advise, allow, permit, invite, encourage, expect, force, teach, warn, remind, persuade, enable, require, cause。\nHe told me to wait. / She asked me to help. / I want you to know.\n否定：tell sb not to do. He told me not to be late.\n注意：let/make/have后接不带to的不定式。",("He told me to wait.","他让我等。"),("She asked me not to be late.","她让我别迟到。"))
A("verb_pattern_v_bare","接不带to不定式","make/let/have sb do","接不带to不定式的动词：\n1. make sb do：He made me cry. (不说made me to cry)\n2. let sb do：She let me go.\n3. have sb do：I had him fix the car.\n注意：\n- 被动语态中to要恢复：I was made to cry.\n- help后可接to do或do：He helped me (to) clean.\n- see/hear/watch sb do(全过程)/doing(正在)。",("He made me laugh.","他让我笑了。"),("She let me go early.","她让我早点走。"))
A("infinitive_perfect","完成不定式","to have done表已完成或过去的动作","完成不定式(to have done)：\n1. 表已完成：He seems to have left. = It seems that he has left.\n2. 表过去：She is said to have written three books. = It is said that she has written...\n3. 否定：not to have done。\n4. 完成进行：to have been doing。\n注意：完成不定式所表动作先于主句动词发生。\nI'm sorry to have kept you waiting. = I'm sorry that I have kept you waiting.",("He seems to have left.","他好像已经走了。"),("She is said to have written three books.","据说她写了三本书。"))
A("infinitive_passive_detail","被动不定式详述","to be done表被动","被动不定式(to be done)：\n1. 表被动：He wants to be promoted.\n2. 完成被动：to have been done。\n   The letter seems to have been sent.\n3. 否定：not to be done。\n注意：\n- 主动表被动：This house is to let(出租). / Blame is to be borne.\n- there be不定式：There is nothing to do(没事做). / There is nothing to be done(没办法了).",("He wants to be promoted.","他想被提拔。"),("The letter seems to have been sent.","信好像已寄出了。"))
A("gerund_perfect","完成动名词","having done表在主句动作之前发生","完成动名词(having done)：\n1. 表先于主句动作：Having finished his homework, he went out.\n2. 完成被动：having been done。\n   Having been told the news, she was happy.\n3. 否定：not having done。\n   Not having received a reply, I wrote again.\n注意：\n- 一般动名词(doing)和完成动名词(having done)都表先于主句。\n- 完成动名词强调时间先后。\n- regret having done = regret doing(后悔做了)。",("Having finished his work, he went home.","完成工作后他回家了。"),("Not having received a reply, I wrote again.","没收到回复，我又写了。"))
A("gerund_passive_detail","被动动名词详述","being done表被动进行","被动动名词(being done)：\n1. 表被动：He dislikes being criticized.\n2. 完成被动：having been done。\n3. 否定：not being done。\n注意：\n- need/want/deserve/require + doing = being done(主动表被动)。\n  My car needs washing. = My car needs to be washed.\n- worth + doing(主动表被动)：The book is worth reading.",("He dislikes being criticized.","他不喜欢被批评。"),("My car needs washing.","我的车该洗了。"))
A("participle_perfect_detail","完成分词详述","having done作状语表先于主句动作","完成分词(having done)：\n1. 作状语表时间/原因：Having finished his work, he went home. / Having lived here for years, he knows the place well.\n2. 完成被动：having been done。Having been invited, he attended the party.\n3. 否定：not having done。Not having enough money, he couldn't buy it.\n注意：\n- 分词的逻辑主语须与主句主语一致。\n- 完成分词强调先于主句动作。\n- 一般分词也可表先后：Finishing his work, he went home.",("Having finished his work, he went home.","完成工作后他回家了。"),("Having been invited, he came to the party.","被邀请后他来参加了聚会。"))
A("participle_passive_detail","被动分词详述","done表被动和完成","过去分词(done)的用法：\n1. 作定语(表被动/完成)：broken glass, fallen leaves, written language。\n2. 作表语：He was excited. / The door is closed.\n3. 作状语：Seen from the hill, the city looks beautiful.\n4. 作宾补：I had my hair cut. / He found the window broken.\n注意：\n- 及物动词的过去分词表被动。\n- 不及物动词的过去分词表完成：fallen leaves(已落的叶)。\n- being done表正在被做。",("Seen from the hill, the city is beautiful.","从山上看，城市很美。"),("He found the window broken.","他发现窗户破了。"))
A("participle_independent_detail","独立主格详述","名词+分词有自己的逻辑主语","独立主格结构：\n1. 名词/代词 + 分词：Weather permitting, we'll go out. (weather是permitting的逻辑主语)\n2. 名词/代词 + 形容词：He stood there, his eyes wide.\n3. 名词/代词 + 介词短语：She entered, a smile on her face.\n4. 名词/代词 + 副词：The meeting over, everyone left.\n5. with + 名词 + 补语：He slept with the window open.\n注意：独立主格的主语与主句主语不同，表伴随/时间/原因/条件。",("Weather permitting, we'll go out.","天气好我们就出门。"),("The meeting over, everyone left.","会议结束，大家都走了。"))
A("with_structure_detail","with复合结构详述","with+宾语+补语(分词/形容词/副词/不定式/介词)","with复合结构：\n1. with + 名词 + 形容词：He slept with the window open.\n2. with + 名词 + 副词：She left with the light on.\n3. with + 名词 + 介词短语：He came in with a book in his hand.\n4. with + 名词 + 现在分词(主动)：With him standing there, I felt nervous.\n5. with + 名词 + 过去分词(被动/完成)：With the work finished, he went home.\n6. with + 名词 + 不定式(将来)：With so much work to do, I can't rest.\n用法：表伴随/方式/原因/条件。",("He slept with the window open.","他开着窗睡觉。"),("With the work done, he relaxed.","工作做完后他放松了。"))
A("tag_question_basic","反义疑问句基础","前肯后否/前否后肯，用助动词和代词","反义疑问句基本规则：\n1. 前肯后否：He is a teacher, isn't he?\n2. 前否后肯：She doesn't like tea, does she?\n3. 用助动词(be/do/have/情态)：You can swim, can't you?\n4. 代词代替名词：Tom is here, isn't he? (不说isn't Tom?)\n5. 时态一致：You went there, didn't you?\n注意：\n- there be句型：There is a book, isn't there?\n- let's开头用shall we：Let's go, shall we?\n- 祈使句用will you：Open the door, will you?",("He is a teacher, isn't he?","他是老师，不是吗？"),("You don't like tea, do you?","你不喜欢茶，对吗？"))
A("tag_question_special","反义疑问句特殊","nothing/never/nobody否定词后用肯定","反义疑问句特殊情况：\n1. 含否定词(no/nothing/never/nobody/hardly/seldom)：\n   He never lies, does he? (前否后肯)\n   Nobody knows, do they?\n2. 含un-/in-/dis-等否定前缀的词不算否定：\n   He is unhappy, isn't he? (unhappy不算否定)\n3. I think/suppose/believe后：\n   I think he is right, isn't he? (问从句)\n   I don't think he is right, is he?\n4. everything/anything用it：Everything is fine, isn't it?\n5. everyone/everybody用they：Everyone is here, aren't they?",("He never lies, does he?","他从不说谎，对吧？"),("I think he is right, isn't he?","我觉得他对，不是吗？"))
A("tag_question_imperative","祈使句反义疑问","祈使句后用will you/won't you","祈使句的反义疑问句：\n1. 肯定祈使句：Open the door, will you? / won't you?\n2. 否定祈使句：Don't open the door, will you?\n3. Let's开头：Let's go, shall we? (含说话人)\n4. Let us开头：Let us go, will you? (不含听话人)\n注意：\n- will you表请求；won't you表邀请。\n- shall we仅用于Let's。\n- 也可用can you/could you使语气更委婉。",("Open the door, will you?","开门好吗？"),("Let's go, shall we?","我们走吧？"))
A("emphasis_do_did","do/does/did强调","用do/does/did强调谓语动词","强调谓语动词：\n1. 强调现在时：I do like it. / She does work hard.\n2. 强调过去时：He did come yesterday.\n3. 强调祈使句：Do be careful! / Do sit down!\n注意：\n- do/does/did后接动词原形。\n- 只强调肯定句，不用于否定句/疑问句。\n- 常用于反驳或强调：— You don't like it. — I do like it!",("I do like this movie.","我确实喜欢这部电影。"),("He did come yesterday.","他昨天确实来了。"))
A("emphasis_position","强调位置","通过词序变化强调句中成分","通过位置变化强调：\n1. 宾语前置：This I must see. / Money he has none.\n2. 状语前置：Yesterday I saw him. / In the room sat a boy.\n3. 倒装强调：Never have I seen such a thing.\n4. 分裂句强调：It was Tom who broke the window.\n5. 助动词强调：I am trying. / Do be careful.\n注意：前置成分通常有对比或强调意味。",("This I must see.","这个我必须看看。"),("Never have I seen such beauty.","我从没见过这样的美。"))
A("sentence_coordination","并列句","用and/but/or/so等连接两个独立分句","并列句由并列连词连接两个或以上独立分句：\n1. and(并列)：I like tea and he likes coffee.\n2. but(转折)：He is rich but unhappy.\n3. or(选择)：Hurry up or you'll be late.\n4. so(因果)：It rained, so I stayed home.\n5. for(原因)：He must be ill, for he looks pale.\n6. yet(转折)：She tried hard, yet she failed.\n7. nor(否定并列)：He can't sing, nor can he dance.\n注意：分句间用逗号分隔。",("I like tea and he likes coffee.","我喜欢茶他喜欢咖啡。"),("Hurry up, or you'll be late.","快点否则会迟到。"))
A("parallel_structure","平行结构","用相同语法结构保持句子平衡","平行结构要求并列成分语法形式一致：\n1. 动词并列：She likes reading, writing, and swimming.\n2. 不定式并列：I want to eat, to sleep, and to play.\n3. 形容词并列：He is tall, strong, and handsome.\n4. 介词短语并列：in the morning, at noon, and in the evening.\n5. 从句并列：that he came, that he helped, and that he left.\n注意：not only...but also, either...or, neither...nor等关联连词也要求平行。",("She likes reading, writing, and swimming.","她喜欢阅读、写作和游泳。"),("He is tall, strong, and handsome.","他又高又壮又帅。"))

# === MASTERY 精通语法 83条 (L5) ===
# 修辞手法 20条
_RH=[
("rheto_metaphor","隐喻Metaphor","直接把A说成B，不用like/as","隐喻不使用like/as，直接将一物说成另一物，隐含比较。增强表达力和形象感。","Time is money.","时间就是金钱。"),
("rheto_simile","明喻Simile","用like/as将两物相比","明喻用like/as/as...as进行明确比较：as brave as a lion。","She is as busy as a bee.","她像蜜蜂一样忙碌。"),
("rheto_personification","拟人Personification","赋予非人事物以人的特征","拟人把无生命事物赋予人的行为或情感。","The wind whispered through the trees.","风在树间低语。"),
("rheto_hyperbole","夸张Hyperbole","故意夸大或缩小","夸张为强调效果故意言过其实。","I've told you a million times.","我跟你说过一百万次了。"),
("rheto_irony","反语Irony","正话反说，字面与实际相反","反语说出的话与真实意思相反，含讽刺意味。","What a wonderful day to be stuck in traffic.","堵车真是美好的一天。"),
("rheto_sarcasm","讽刺Sarcasm","用尖刻话语嘲讽","讽刺用尖刻话语直接嘲讽，常伤人。","Nice going, genius.","干得漂亮，天才。"),
("rheto_litotes","间接肯定Litotes","用否定反义词来肯定","Litotes用双重否定或否定反义词表肯定：not bad=good。","He's not unkind.","他并非不善良。"),
("rheto_metonymy","转喻Metonymy","用相关事物代本体","转喻用相关事物代替本体：the crown=王权，the White House=美国政府。","The pen is mightier than the sword.","笔比剑更有力。"),
("rheto_synecdoche","提喻Synecdoche","以部分代整体或整体代部分","提喻用部分代整体(all hands=所有船员)或整体代部分。","He bought new wheels.","他买了新车。"),
("rheto_oxymoron","矛盾修饰Oxymoron","矛盾词语并列","矛盾修饰将反义词并列：bittersweet, living death。","It was a bittersweet memory.","那是苦甜参半的回忆。"),
("rheto_paradox","悖论Paradox","看似矛盾实含真理","悖论看似自相矛盾却含真理：Less is more。","The child is father of the man.","三岁定八十。"),
("rheto_antithesis","对偶Antithesis","用并列结构对比相反概念","对偶用平行结构对比相反概念：To err is human; to forgive, divine。","Speech is silver, silence is golden.","雄辩是银，沉默是金。"),
("rheto_chiasmus","交错配列Chiasmus","ABBA交叉结构","交错配列将词序交叉排列：Ask not what your country can do for you—ask what you can do for your country。","You can take the boy out of the country, but you can't take the country out of the boy.","你可以让男孩离开乡村，但乡村不会离开男孩。"),
("rheto_anaphora","首语重复Anaphora","句首重复相同词组","首语重复在连续句首重复同一词组，增强气势。","I have a dream that one day... I have a dream that...","我有一个梦想……我有一个梦想……"),
("rheto_epistrophe","尾词重复Epistrophe","句末重复相同词","尾词重复在句末重复同一词。","When I was a child, I spoke as a child, I understood as a child.","作孩子时，我说话像孩子，理解像孩子。"),
("rheto_apostrophe","呼语Apostrophe","对不在场者或抽象事物说话","呼语对不在场的人、神或抽象事物直接呼告。","O Death, where is thy sting?","死亡啊，你的毒钩在哪里？"),
("rheto_euphemism","委婉语Euphemism","用温和词替代刺耳词","委婉语用温和词汇替代冒犯或不愉快词语：pass away=die。","He passed away last night.","他昨晚去世了。"),
("rheto_alliteration","头韵Alliteration","首辅音重复","头韵重复词首辅音，增强音韵效果。","Peter Piper picked a peck of pickled peppers.","彼得·派珀捡了一配克腌胡椒。"),
("rheto_assonance","元音谐音Assonance","元音重复","元音谐音重复相同元音。","The rain in Spain falls mainly on the plain.","西班牙的雨主要落在平原上。"),
("rheto_onomatopoeia","拟声Onomatopoeia","词模拟自然声音","拟声词模仿自然声音：buzz, hiss, splash, cuckoo。","The bees buzzed and the snake hissed.","蜜蜂嗡嗡蛇嘶嘶。"),
]
for mid,t,s,d,ee,ec in _RH:
    M(mid,t,s,d,(ee,ec))

# 句式多样性 10条
_SV=[
("sent_simple","简单句Simple","一个主谓结构","简单句只含一个独立主谓结构，表达单一完整意思。","The cat sat on the mat.","猫坐在垫子上。"),
("sent_compound","并列句Compound","用连词连接独立分句","并列句用and/but/or/so等连接两个或以上独立分句。","She sang and he danced.","她唱歌他跳舞。"),
("sent_complex","复合句Complex","独立分句+从句","复合句含一个独立分句和一个或以上从句。","When she arrived, the meeting had started.","她到时会议已开始。"),
("sent_compound_complex","并列复合句","并列+复合结构","并列复合句含两个以上独立分句和一个以上从句。","She sang, and he danced because it was a party.","她唱歌，他跳舞因为那是派对。"),
("sent_periodic","圆周句Periodic","主句在末尾，制造悬念","圆周句把主要信息放句末，前面铺垫，制造悬念。","Despite the rain, the cold, and the lateness of the hour, she came.","尽管下雨寒冷夜深，她还是来了。"),
("sent_loose","松散句Loose","主句在前，补充在后","松散句主句在前，后续信息逐层补充，自然平易。","She came, despite the rain, the cold, and the hour.","她来了，尽管下雨寒冷夜深。"),
("sent_balanced","平衡句Balanced","两个对等分句对称","平衡句两个结构对称的分句，常用于对比。","To err is human; to forgive, divine.","犯错是人之常情，宽恕是神圣的。"),
("sent_cumulative","累积句Cumulative","主句后接多个补充短语","累积句主句后接递增的修饰短语，层层展开细节。","He ran, breathless, determined, unstoppable.","他跑着，气喘吁吁，决心坚定，不可阻挡。"),
("sent_suspended","悬念句Suspended","关键信息延后","悬念句把关键信息延后揭示。","The winner of the contest, after hours of deliberation, was finally announced.","经过数小时审议，比赛获胜者终于公布。"),
("sent_antithetical","对立句Antithetical","并列结构中对比对立","对立句在并列结构中对比两个对立概念。","It was the best of times, it was the worst of times.","那是最好的时代，那是最坏的时代。"),
]
for sid,t,s,d,ee,ec in _SV:
    M(sid,t,s,d,(ee,ec))

# 衔接与过渡词 15条
_TR=[
("trans_additive","递进过渡Additive","also, moreover, furthermore","递进过渡词补充新信息：also, in addition, moreover, furthermore, besides。","She is smart; moreover, she is hardworking.","她聪明；此外，她勤奋。"),
("trans_adversative","转折过渡Adversative","however, nevertheless, yet","转折过渡词表示对比或转折：however, nevertheless, on the other hand。","He tried hard; however, he failed.","他很努力；然而，他失败了。"),
("trans_causal","因果过渡Causal","therefore, thus, consequently","因果过渡词表示原因结果：therefore, thus, consequently, as a result。","It rained; therefore, we stayed home.","下雨了；因此我们待在家。"),
("trans_sequential","顺序过渡Sequential","first, then, next, finally","顺序过渡词表示时间或逻辑顺序：first, second, then, next, finally。","First, mix the flour; then, add eggs; finally, bake.","先混合面粉；然后加蛋；最后烘焙。"),
("trans_illustrative","举例过渡Illustrative","for example, for instance","举例过渡词引出具体例证：for example, for instance, such as。","Many fruits are red; for example, apples and cherries.","很多水果是红的；例如苹果和樱桃。"),
("trans_concluding","总结过渡Concluding","in conclusion, to sum up","总结过渡词引出结论：in conclusion, to sum up, in summary。","In conclusion, we must act now.","总之，我们必须立即行动。"),
("trans_summarizing","概括过渡Summarizing","in short, overall, generally","概括过渡词对前文进行概括：in short, overall, all in all。","Overall, the project was a success.","总体而言，项目是成功的。"),
("trans_emphasis","强调过渡Emphasis","indeed, in fact, certainly","强调过渡词突出重要信息：indeed, in fact, certainly, of course。","He is, indeed, the best candidate.","他确实是最佳人选。"),
("trans_comparison","比较过渡Comparison","similarly, likewise, equally","比较过渡词指出相似：similarly, likewise, in the same way。","She loves reading; similarly, her brother enjoys books.","她爱阅读；同样，她哥哥也爱书。"),
("trans_contrast","对比过渡Contrast","in contrast, on the contrary","对比过渡词指出差异：in contrast, on the contrary, conversely。","Tom is tall; in contrast, Jerry is short.","汤姆高；相反，杰瑞矮。"),
("trans_condition","条件过渡Condition","otherwise, if so, if not","条件过渡词引出条件：otherwise, if so, if not, in that case。","Hurry up; otherwise, you'll be late.","快点；否则你会迟到。"),
("trans_concession","让步过渡Concession","granted, of course, admittedly","让步过渡词承认某点：granted, admittedly, of course, to be sure。","Admittedly, the plan has flaws.","不可否认，计划有缺陷。"),
("trans_purpose","目的过渡Purpose","for this purpose, to this end","目的过渡词说明目的：for this purpose, to this end。","We need funding; to this end, we'll apply for a grant.","我们需要资金；为此，我们将申请拨款。"),
("trans_result","结果过渡Result","as a result, accordingly","结果过渡词表示后果：as a result, accordingly, hence。","He overslept; as a result, he missed the train.","他睡过头；结果错过了火车。"),
("trans_reformulation","换言过渡Reformulation","in other words, that is","换言过渡词重新表述：in other words, that is, namely。","He's a polyglot; in other words, he speaks many languages.","他是通晓多语者；换言之，他会多种语言。"),
]
for tid,t,s,d,ee,ec in _TR:
    M(tid,t,s,d,(ee,ec))

# 学术写作与正式语法 15条
_AW=[
("acad_nominalization","名词化Nominalization","动词/形容词转为名词","名词化将动词或形容词转为名词，使表达更正式抽象：decide→decision, important→importance。","The decision was made quickly.","决定很快做出了。"),
("acad_passive_use","学术被动","学术中多用被动强调过程","学术写作多用被动语态，强调过程而非执行者。","The experiment was conducted carefully.","实验被仔细进行。"),
("acad_hedging","模糊限制Hedging","用may/might/seem等避免绝对","模糊限制语避免绝对化断言：may, might, seem, tend to, suggest。","The results may indicate a trend.","结果可能表明一种趋势。"),
("acad_cautious_language","谨慎措辞Cautious Language","避免过于肯定","谨慎措辞用it seems/appears that, arguably, presumably。","It appears that the theory is valid.","这个理论似乎是有效的。"),
("acad_impersonal","无人称结构Impersonal","避免I/we，用it/there","无人称结构避免主观：It is argued that... / There is evidence that...。","It is widely believed that exercise is beneficial.","人们普遍认为运动有益。"),
("acad_cleft_emphasis","学术分裂句强调","It is X that...强调","分裂句用于强调：It is collaboration that drives innovation。","It is through practice that one masters a skill.","正是通过练习才能掌握技能。"),
("acad_fronting","学术前置Fronting","将重要信息前置","前置把重要或对比信息放句首。","This theory, Einstein proposed in 1905.","这个理论，爱因斯坦于1905年提出。"),
("acad_formal_inversion","正式倒装","正式文体中倒装","正式文体常用倒装：Rarely have we seen... / Not only did he...but...。","Rarely has such a discovery been made.","如此发现实属罕见。"),
("acad_subjunctive_formal","正式虚拟","demand/insist后用虚拟","正式文体中demand/insist/suggest/recommend后用should+原形或直接原形。","The committee insisted that he resign.","委员会坚持他辞职。"),
("acad_absolute_phrase","独立短语Absolute Phrase","名词+分词作状语","独立短语(名词+分词)作状语，表伴随或补充。","The meeting being over, everyone left.","会议结束，大家都走了。"),
("acad_participial_phrase","分词短语","Ving/V-ed作状语定语","分词短语作状语或定语，使句子紧凑。","Having finished his work, he left.","完成工作后他离开了。"),
("acad_appositive","同位语Appositive","名词后补充说明","同位语对前面名词补充说明，用逗号隔开。","Beijing, the capital of China, is huge.","北京，中国的首都，很大。"),
("acad_relative_reduction","定语从句简化","省略关系代词+be","定语从句简化：The man (who is) standing there。","The book written by him is popular.","他写的书很受欢迎。"),
("acad_dangling_modifier","悬垂修饰语Dangling Modifier","分词逻辑主语与主句不一致","悬垂修饰语的分词逻辑主语与主句主语不一致，属语法错误。","Walking down the street, the trees were beautiful.(误)","走在街上，树很美。（错误句）"),
("acad_misplaced_modifier","错位修饰语Misplaced Modifier","修饰语位置不当造成歧义","错位修饰语位置不当导致歧义。","She almost drove the car for six hours.(歧义)","她几乎开了六小时车。（歧义）"),
]
for aid,t,s,d,ee,ec in _AW:
    M(aid,t,s,d,(ee,ec))

# 语篇与语用 10条
_DP=[
("disc_speech_acts","言语行为Speech Acts","语言即行为：陈述/命令/承诺","言语行为理论：语言不仅是描述，也是行为(陈述/命令/承诺/道歉)。","I promise to help.","我承诺帮忙。"),
("disc_implicature","会话含义Implicature","言外之意","会话含义理论：字面之外的含义，依赖语境推断。","It's cold in here.（暗示关窗）","这里好冷。（暗示关窗）"),
("disc_presupposition","预设Presupposition","说话前的背景假设","预说是话语中已假定为真的背景信息。","John stopped smoking.（预设John曾吸烟）","约翰戒烟了。（预设他曾吸烟）"),
("disc_deixis","指示Deixis","this/here/now等依赖语境","指示词(this/that/here/there/now/then)依赖语境确定所指。","Come here now.","现在来这里。"),
("disc_cohesion","衔接Cohesion","语法词汇手段连接语篇","衔接用照应、替代、省略、连接词等手段连接语篇。","She bought a book. It was good.","她买了本书。它很好。"),
("disc_coherence","连贯Coherence","语篇逻辑意义一致","连贯指语篇在意义和逻辑上一致，不仅形式衔接。","She loves animals. She works at a zoo.","她爱动物。她在动物园工作。"),
("disc_register","语域Register","语言正式程度随场合变化","语域指语言随场合(正式/非正式/学术/口语)变化的程度。","G'day mate!（口语）/ Good morning, sir.（正式）","早啊伙计！/早上好，先生。"),
("disc_genre","体裁Genre","文本类型决定结构","体裁指文本类型(叙事/议论/说明/描写)，决定结构和语言。","Once upon a time...（叙事体裁）","从前……"),
("disc_modality","情态Modality","表达可能性/必要性/义务","情态表达说话人对命题的态度：可能性、必要性、义务。","You must finish it today.","你必须今天完成。"),
("disc_stance","立场Stance","表达作者态度","立场表达作者对信息的评价和态度：certainly, perhaps, surprisingly。","Surprisingly, he agreed.","令人惊讶的是，他同意了。"),
]
for did,t,s,d,ee,ec in _DP:
    M(did,t,s,d,(ee,ec))

# 风格与机械规范 13条
_ST=[
("style_parallelism_lists","列表平行","并列项语法形式一致","列表中并列项必须语法形式一致。","She likes reading, writing, and swimming.","她喜欢阅读、写作和游泳。"),
("style_series_comma","牛津逗号","并列最后一项前的逗号","牛津逗号是and前的逗号，避免歧义。","I thank my parents, Ayn Rand, and God.","我感谢我的父母、安·兰德和上帝。"),
("style_split_infinitive","分裂不定式","to与动词间插入副词","分裂不定式在to和动词间插入副词，正式写作中尽量避免。","To boldly go...（争议用法）","勇敢地去……"),
("style_fragment","句子碎片Fragment","不完整句子","句子碎片缺少主语或谓语，不成完整句。","Because I said so.（碎片）","因为我说了算。（碎片）"),
("style_run_on","连写句Run-on","两句间无标点或连词","连写句两个独立句间无标点或连词。","It is late I must go.（连写误）","很晚了我得走。（错误）"),
("style_comma_splice","逗号粘连Comma Splice","两独立句只用逗号连接","逗号粘连错误地用逗号连接两个独立分句。","It is late, I must go.（误）","很晚了，我得走。（错误）"),
("style_agreement_errors","一致性错误Agreement","主谓/代词不一致","主谓一致和代词一致错误。","He don't know.（误，应为doesn't）","他不知道。（错误）"),
("style_pronoun_reference","代词指代","代词须有明确先行词","代词必须有明确的先行词，否则造成歧义。","When Tom met Jerry, he smiled.（he指谁？）","汤姆遇到杰瑞时，他笑了。（he指谁？）"),
("style_point_of_view","视角一致","保持一致的人称视角","句子中应保持一致的人称(第一/二/三人称)。","If one studies hard, you will succeed.（误，人称不一致）","如果努力学习，你就会成功。（错误）"),
("style_tense_consistency","时态一致","段落内时态应一致","段落内时态应保持一致，避免无谓跳跃。","She walked in and sits down.（误，时态不一致）","她走进来并坐下。（错误）"),
("style_capitalization","大写规则","句首/专有名词/I大写","大写规则：句首字母、专有名词、代词I、标题实词大写。","I live in Beijing.","我住在北京。"),
("style_punctuation_basic","标点基础","句号/逗号/分号/冒号用法","标点基础：句号结束陈述句；逗号分隔并列项；分号连接相关独立句；冒号引出解释。","She bought apples, bananas, and oranges.","她买了苹果、香蕉和橘子。"),
("style_active_vs_passive_choice","主动被动选择","主动更直接，被动强调承受者","主动语态更直接有力，被动语态强调动作承受者或执行者不重要。","The committee approved the plan.（主动）/ The plan was approved.（被动）","委员会批准了计划。/计划被批准了。"),
]
for sid,t,s,d,ee,ec in _ST:
    M(sid,t,s,d,(ee,ec))

# === ADVANCED 补充 33条 (L4) ===
_AD=[
("cond_mixed_present_past","混合条件句(现在过去)","主从时态不同","混合条件句：If I had studied harder (过去), I would be richer now (现在)。主从时间不同。","If I had studied medicine, I would be a doctor now.","如果我学医，现在就是医生了。"),
("cond_omitted_if","省略if","if省略+倒装","正式条件句中省略if，用倒装：Had I known, I would have come. / Were I you, I would go. / Should it rain, I'll stay.","Had I known, I would have come.","早知道我就来了。"),
("cond_inverted","倒装条件句","had/were/should+主语+...","倒装条件句：Had+S+done, Were+S+to do, Should+S+do。","Were I you, I would accept.","如果我是你，我会接受。"),
("cond_implicit","含蓄条件句","无if但有条件意","含蓄条件句不出现if，但暗含条件：But for your help, I would have failed. / Without water, we would die. / I would have helped, but I was busy.","But for your help, I would have failed.","没有你的帮助，我就失败了。"),
("cond_unless_provided","unless/provided/as long as","其他条件连词","其他条件连词：unless(除非), provided/providing that(只要), as long as(只要), on condition that(条件是), suppose/supposing(假设)。","You can borrow it as long as you return it tomorrow.","只要明天还，你就可以借。"),
("inv_negative","否定词倒装","否定词前置+助动词倒装","否定词(negative_adverbial)放句首时主句倒装：Never/Seldom/Hardly/Rarely/Little/Scarcely+助动词+S。","Never have I seen such beauty.","我从没见过这样的美。"),
("inv_only","only倒装","only+状语前置倒装","only+状语放句首时主句倒装：Only then/Only by/Only when+助动词+S。","Only then did I understand.","那时我才明白。"),
("inv_so_such","so/such倒装","so/such...that倒装","so+adj/adv或such+n放句首时，主句倒装：So beautiful was she that everyone stared. / Such was his anger that he left.","So angry was he that he left.","他如此生气以至于走了。"),
("inv_here_there","here/there倒装","here/there+动词+主语","here/there放句首，动词在主语前(主语为名词时倒装，代词时不倒装)：Here comes the bus. / Here it comes.","Here comes the train.","火车来了。"),
("inv_balance","平衡倒装","为平衡句子倒装","为平衡句子或强调而倒装：On the table sat a cat. / Through the window came a beam of light. (介词短语前置)","On the wall hung a picture.","墙上挂着一幅画。"),
("vcomp_n_adj","V+N+adj","动词+宾语+形容词作宾补","V+N+adj(宾补)：make/keep/find/leave/paint+N+adj。","She painted the door red.","她把门漆成红色。"),
("vcomp_n_todo","V+N+to do","动词+宾语+不定式","V+N+to do：want/wish/ask/tell/allow+N+to do。","I asked him to help.","我请他帮忙。"),
("vcomp_n_doing","V+N+doing","动词+宾语+现在分词","V+N+doing：keep/catch/find/leave+N+doing。","I caught him stealing.","我抓到他偷东西。"),
("vcomp_n_do","V+N+do","动词+宾语+原形","V+N+do(无to)：make/let/have/see/hear/watch+N+do。","She made him cry.","她让他哭了。"),
("vcomp_that","V+that从句","动词+that宾语从句","V+that：think/believe/say/know/hope+that...。","I think that he is right.","我认为他对。"),
("vcomp_wh_todo","V+wh+to do","动词+疑问词+不定式","V+wh-+to do：know/decide/wonder/ask+wh-+to do。","I don't know what to do.","我不知道该做什么。"),
("vcomp_it_adj_todo","V+it+adj+to do","动词+it+形容词+不定式","V+it+adj+to do：make/find/feel+it+adj+to do。","I find it hard to learn Chinese.","我觉得学中文难。"),
("vcomp_reflexive","V+反身代词","动词+反身代词","V+反身代词：enjoy/hurt/teach/introduce+oneself。","She taught herself English.","她自学英语。"),
("modal_shall_will","shall vs will","shall用于第一人称征求意见/承诺","shall用于第一人称征求意见(Shall I...?)或承诺/威胁(You shall get it)。will表将来或意愿。","Shall we dance?","我们跳舞吗？"),
("modal_should_have","should have done","本该做却没做","should have done表过去本该做却没做，含责备。","You should have told me.","你本该告诉我。"),
("modal_could_have","could have done","本可以做却没做","could have done表过去本可以做却没做，表可能性或遗憾。","I could have won.","我本可以赢。"),
("modal_may_have","may have done","可能已经做了","may have done表对过去事情的推测(可能已经)。","He may have left already.","他可能已经走了。"),
("modal_must_have","must have done","一定已经做了","must have done表对过去事情的肯定推测(一定已经)。","You must have been tired.","你一定累了。"),
("adv_subjunctive_demand","demand型虚拟","demand/insist/suggest后用虚拟","demand/insist/suggest/recommend/require/order+that+S+(should)+V原形。","The doctor insisted that he rest.","医生坚持让他休息。"),
("adv_subjunctive_wish_past","wish与过去相反","wish+过去完成时","wish+过去完成时表与过去事实相反的愿望：I wish I had studied harder. (真希望当时更努力)","I wish I had studied harder.","我真希望当时更努力。"),
("adv_subjunctive_as_if","as if/as though虚拟","as if+虚拟语气表非真实","as if/as though后用虚拟语气表非真实情况：He talks as if he knew everything. (其实不懂)","He talks as if he knew everything.","他说话好像什么都知道。"),
("adv_subjunctive_it_time","It's time虚拟","It's (high) time+S+过去时","It's (high) time+S+过去时(虚拟)，表'该做某事了'。","It's time we left.","我们该走了。"),
("adv_subjunctive_would_rather","would rather虚拟","would rather+S+过去时","would rather+S+过去时(对现在/将来虚拟)：I'd rather you didn't smoke. / would rather+S+过去完成时(对过去)。","I'd rather you didn't smoke.","我宁愿你不抽烟。"),
("adv_elliptical_clause","省略从句","省略主语或be","省略从句：While (he was) reading, he fell asleep. / Though (he was) tired, he worked on.","While reading, he fell asleep.","看书时他睡着了。"),
("adv_absolute_nominative","独立主格主格","名词+分词有自己的逻辑主语","独立主格：名词/代词+分词/形容词/副词/不定式/介词短语，有自己的逻辑主语。","Weather permitting, we'll go out.","天气允许我们就出门。"),
("adv_absolute_with","with独立结构","with+名词+补语","with+名词+分词/形容词/副词/不定式/介词短语，表伴随。","He slept with the window open.","他开着窗睡觉。"),
("adv_if_only","if only虚拟","if only+虚拟表强烈愿望","if only+虚拟语气表强烈愿望：If only I were younger! / If only I had listened!","If only I were younger!","要是我更年轻就好了！"),
("adv_it_is_high_time","It is high time","It is high time+S+过去时","It is high time+S+过去时，表'早该做某事了'。","It is high time we left.","我们早该走了。"),
]
for aid,t,s,d,ee,ec in _AD:
    A(aid,t,s,d,(ee,ec))

# === 写入文件并打印统计 ===
import os
out = {"version": 1, "topics": topics}
out_path = os.path.join(os.path.dirname(os.path.dirname(os.path.abspath(__file__))), "data", "grammar_extra.json")
os.makedirs(os.path.dirname(out_path), exist_ok=True)
with open(out_path, "w", encoding="utf-8") as f:
    f.write(json.dumps(out, ensure_ascii=False, indent=2))

size = os.path.getsize(out_path)
from collections import Counter
cat_count = Counter(t["category"] for t in topics)
print("=== 语法数据生成完成 ===")
print(f"总条数: {len(topics)}")
for cat in ["basics", "tense", "clause", "advanced", "mastery"]:
    print(f"  {cat}: {cat_count.get(cat, 0)} 条")
print(f"文件大小: {size} 字节 ({size/1024/1024:.2f} MB)")
print(f"输出路径: {out_path}")
